            if (check(set, i)) {
                res++;
            }
        }
        return res;
    }

    private boolean check(Set<Integer> set, int gcd) {
        int g = 0;
        for (int num : set) {
            if (num % gcd == 0) {
                g = gcd(g, num);
                if (g == gcd) {
                    return true;
                }
            }
        }
        return false;
    }

    private int gcd(int a, int b) {
        if (b == 0) {
            return a;
        } else {
            return gcd(b, a % b);
        }
    }
}

