    public int getNumberOfBacklogOrders(int[][] orders) {
        PriorityQueue<int[]> buy = new PriorityQueue<>((a, b) -> b[0] - a[0]);
        PriorityQueue<int[]> sell = new PriorityQueue<>((a, b) -> a[0] - b[0]);

        for (int[] order : orders) {
            if (order[2] == 0) { // buy
                while (!sell.isEmpty() && sell.peek()[0] <= order[0]) {
                    int[] s = sell.poll();
                    if (s[1] > order[1]) {
                        s[1] -= order[1];
                        sell.offer(s);
                        break;
                    } else {
                        order[1] -= s[1];
                        if (order[1] == 0) break;
                    }
                }
                if (order[1] != 0) buy.offer(order);
            } else { // sell
                while (!buy.isEmpty() && buy.peek()[0] >= order[0]) {
                    int[] b = buy.poll();
                    if (b[1] > order[1]) {
                        b[1] -= order[1];
                        buy.offer(b);
                        break;
                    } else {
                        order[1] -= b[1];
                        if (order[1] == 0) break;
                    }
                }
                if (order[1] != 0) sell.offer(order);
            }
        }

        int res = 0;
        while (!buy.isEmpty()) res += buy.poll()[1];
        while (!sell.isEmpty()) res += sell.poll()[1];

        return res % (int) (Math.pow(10, 9) + 7);
    }
