public class Solution {
    public int minFlips(String expression) {
        Stack<Result> stack = new Stack<>();
        for (char c : expression.toCharArray()) {
            if (c == '(') {
                stack.push(new Result(0, 0));
            } else if (c == ')') {
                Result r1 = stack.pop();
                Result r2 = stack.pop();
                int minFlips = Math.min(r1.minFlips + r2.minFlips, 
                                        r1.val == 1 ? r2.minFlips : r1.minFlips);
                if (r1.val != r2.val) {
                    minFlips++;
                }
                stack.push(new Result(r1.val | r2.val, minFlips));
            } else if (c == '&') {
                Result r1 = stack.pop();
                Result r2 = stack.pop();
                int minFlips = Math.min(r1.minFlips + r2.minFlips, 
                                        r1.val == 0 ? r2.minFlips : r1.minFlips);
                if (r1.val != r2.val) {
                    minFlips++;
                }
                stack.push(new Result(r1.val & r2.val, minFlips));
            } else if (c == '|') {
                Result r1 = stack.pop();
                Result r2 = stack.pop();
                int minFlips = Math.min(r1.minFlips + r2.minFlips, 
                                        r1.val == 0 ? r2.minFlips : r1.minFlips);
                if (r1.val != r2.val) {
                    minFlips++;
                }
                stack.push(new Result(r1.val | r2.val, minFlips));
            } else {
                int val = c - '0';
                stack.push(new Result(val, 1 - val));
            }
        }
        return stack.pop().minFlips;
    }

    public class Solution {
        int val;
        int minFlips;

        public Result(int val, int minFlips) {
            this.val = val;
            this.minFlips = minFlips;
        }
    }
