public class Solution {
    public int minSkips(int[] dist, int speed, int hoursBefore) {
        int n = dist.length;
        long[][] dp = new long[n + 1][n + 1];
        for (long[] row : dp) {
            java.util.Arrays.fill(row, Long.MAX_VALUE);
        }
        dp[0][0] = 0;

        for (int i = 1; i <= n; i++) {
            dp[i][0] = (dp[i - 1][0] + dist[i - 1]) / speed * speed;
            for (int j = 1; j <= i; j++) {
                dp[i][j] = Math.min(dp[i][j], dp[i - 1][j - 1] + dist[i - 1]);
                if (dp[i - 1][j] != Long.MAX_VALUE) {
                    long val = ((dp[i - 1][j] + dist[i - 1]) / speed * speed);
                    if (val < dp[i][j]) {
                        dp[i][j] = val;
                    }
                }
            }
        }

        for (int j = 0; j <= n; j++) {
            if (dp[n][j] <= hoursBefore * speed) {
                return j;
            }
        }
        return -1;
    }
}

