public class Solution {
    public int longestBeautifulSubstring(String word) {
        char[] chars = word.toCharArray();
        int maxLen = 0;
        int left = 0, right = 1;

        while (right < chars.length) {
            if (chars[right] > chars[right - 1]) {
                right++;
            } else if (chars[right] == chars[right - 1]) {
                if (left != right - 1 && isBeautiful(chars, left, right)) {
                    maxLen = Math.max(maxLen, right - left);
                }
                left = right;
                right++;
            } else {
                if (isBeautiful(chars, left, right)) {
                    maxLen = Math.max(maxLen, right - left);
                }
                left = right;
                right++;
            }
        }

        return isBeautiful(chars, left, chars.length) ? Math.max(maxLen, chars.length - left) : maxLen;
    }

    private boolean isBeautiful(char[] chars, int start, int end) {
        char[] vowels = {'a', 'e', 'i', 'o', 'u'};
        int vowelIndex = 0;

        for (int i = start; i < end; i++) {
            if (chars[i] == vowels[vowelIndex]) {
                while (i + 1 < end && chars[i + 1] == chars[i]) {
                    i++;
                }
                vowelIndex++;
                if (vowelIndex >= vowels.length) {
                    return true;
                }
            } else {
                break;
            }
        }

        return false;
    }
}

