            Integer higher = set.ceiling(nums2[i]);
            if (higher != null) {
                maxDiff = Math.max(maxDiff, diff - Math.abs(higher - nums2[i]));
            }
        }

        return (int) ((sum - maxDiff) % MOD);
    }
}

