public class Solution {
    public int largestPathValue(String colors, int[][] edges) {
        int n = colors.length();
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
        }

        int[][] dp = new int[n][26];
        boolean[] visited = new boolean[n];

        int res = 0;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                if (!dfs(graph, colors, dp, visited, i)) return -1;
            }
            for (int j = 0; j < 26; j++) {
                res = Math.max(res, dp[i][j]);
            }
        }

        return res;
    }

    private boolean dfs(List<Integer>[] graph, String colors, int[][] dp, boolean[] visited, int node) {
        if (visited[node]) return false;

        visited[node] = true;
        for (int nei : graph[node]) {
            if (!dfs(graph, colors, dp, visited, nei)) return false;
            for (int i = 0; i < 26; i++) {
                dp[node][i] = Math.max(dp[node][i], dp[nei][i]);
            }
        }

        dp[node][colors.charAt(node) - 'a']++;
        return true;
    }
}

