// #Graph_Theory_I_Day_9_Standard_Traversal #2022_03_23_Time_7_ms_(74.93%)_Space_71.1_MB_(44.58%)
public class Solution {
    public List<Integer> eventualSafeNodes(int[][] graph) {
        int n = graph.length;
        boolean[] visited = new boolean[n];
        boolean[] safe = new boolean[n];

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                dfs(graph, i, visited, safe);
            }
        }

        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (safe[i]) {
                result.add(i);
            }
        }
        Collections.sort(result);
        return result;
    }

    private void dfs(int[][] graph, int node, boolean[] visited, boolean[] safe) {
        visited[node] = true;

        for (int neighbor : graph[node]) {
            if (!visited[neighbor]) {
                dfs(graph, neighbor, visited, safe);
            }
            if (!safe[neighbor]) {
                safe[node] = false;
            }
        }

        if (graph[node].length == 0 || Arrays.stream(graph[node]).allMatch(neighbor -> safe[neighbor])) {
            safe[node] = true;
        }
    }
}

