public class Solution {
    public int[][] spiralMatrixIII(int rows, int cols, int y, int x) {
        int[][] res = new int[rows * cols][2];
        int index = 0;
        int[] dx = {1, 0, -1, 0};
        int[] dy = {0, 1, 0, -1};
        int dir = 0;

        while (index < rows * cols) {
            if (x >= 0 && x < cols && y >= 0 && y < rows) {
                res[index][0] = y;
                res[index++][1] = x;
            }

            // Move right
            int newX = x + dx[dir];
            int newY = y + dy[dir];

            if (newX < 0 || newX >= cols || newY < 0 || newY >= rows) {
                dir = (dir + 1) % 4;
                newX = x + dx[dir];
                newY = y + dy[dir];
            }

            x = newX;
            y = newY;
        }
        return res;
    }
}

