public class Solution {
    public int minSwap(int[] nums1, int[] nums2) {
        int swap = 0;
        int noSwap = 0;

        for (int i = 1; i < nums1.length; i++) {
            if (nums1[i - 1] >= nums1[i] || nums2[i - 1] >= nums2[i]) {
                int temp = swap;
                swap = noSwap + 1;
                noSwap = temp;
            } else if (nums1[i - 1] >= nums2[i] && nums2[i - 1] >= nums1[i]) {
                swap += 1;
            }
        }

        return Math.min(swap, noSwap);
    }
}

