import java.util.Arrays;
public class Solution {
    public int uniqueLetterString(String s) {
        int res = 0, n = s.length();
        int[] lastCharIdx = new int[26];
        int[] prevLastCharIdx = new int[26];

        Arrays.fill(lastCharIdx, -1);
        Arrays.fill(prevLastCharIdx, -1);

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            int idx = c - 'A';

            res += (i - lastCharIdx[idx]) * (lastCharIdx[idx] - prevLastCharIdx[idx]);

            prevLastCharIdx[idx] = lastCharIdx[idx];
            lastCharIdx[idx] = i;
        }

        for (int i = 0; i < 26; i++) {
            res += (n - lastCharIdx[i]) * (lastCharIdx[i] - prevLastCharIdx[i]);
        }
        return res;
    }
}

