import java.util.HashSet;

public class Solution {
    public int numSpecialEquivGroups(String[] words) {
        HashSet<String> set = new HashSet<>();

        for (String word : words) {
            char[] even = new char[word.length() / 2];
            char[] odd = new char[(word.length() + 1) / 2];

            int eIndex = 0, oIndex = 0;
            for (int i = 0; i < word.length(); i++) {
                if (i % 2 == 0) {
                    even[eIndex++] = word.charAt(i);
                } else {
                    odd[oIndex++] = word.charAt(i);
                }
            }

            sort(even);
            sort(odd);

            StringBuilder sb = new StringBuilder();
            for (char c : even) {
                sb.append(c);
            }
            for (char c : odd) {
                sb.append(c);
            }

            set.add(sb.toString());
        }

        return set.size();
    }

    private void sort(char[] chars) {
        int n = chars.length;
        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j < n - i - 1; j++) {
                if (chars[j] > chars[j + 1]) {
                    char temp = chars[j];
                    chars[j] = chars[j + 1];
                    chars[j + 1] = temp;
                }
            }
        }
    }
}

