import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Solution {
    public int[] sumOfDistancesInTree(int n, int[][] edges) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        int[] count = new int[n];
        int[] res = new int[n];

        dfs(graph, 0, -1, count);
        dfs2(graph, 0, -1, n, count, res);

        return res;
    }

    private void dfs(List<Integer>[] graph, int node, int parent, int[] count) {
        for (int child : graph[node]) {
            if (child != parent) {
                dfs(graph, child, node, count);
                count[node] += count[child];
            }
        }
        count[node]++;
    }

    private void dfs2(List<Integer>[] graph, int node, int parent, int n, int[] count, int[] res) {
        for (int child : graph[node]) {
            if (child != parent) {
                res[child] = res[node] - count[child] + (n - count[child]);
                dfs2(graph, child, node, n, count, res);
            }
        }
    }
}

