public class Solution {
    private static final int MOD = (int) 1e9 + 7;
    private static final int[][] GCD = new int[7][7];

    static {
        for (int i = 0; i < 7; i++) {
            for (int j = 0; j < 7; j++) {
                if (i == 0 || j == 0) {
                    GCD[i][j] = 0;
                } else {
                    GCD[i][j] = gcd(i, j);
                }
            }
        }
    }

    public int distinctSequences(int n) {
        long[][] dp = new long[n + 1][7];
        for (int i = 1; i <= 6; i++) {
            dp[1][i] = 1;
        }
        for (int i = 2; i <= n; i++) {
            for (int j = 1; j <= 6; j++) {
                for (int k = 1; k <= 6; k++) {
                    if ((GCD[j][k] == 1) && (i - lastPos(dp, j, i - 1)) > 2) {
                        dp[i][j] += dp[i - 1][k];
                        dp[i][j] %= MOD;
                    }
                }
            }
        }

        long sum = 0;
        for (int i = 1; i <= 6; i++) {
            sum += dp[n][i];
            sum %= MOD;
        }
        return (int) sum;
    }

    private int lastPos(long[][] dp, int val, int row) {
        for (int i = row - 1; i >= 0; i--) {
            if (dp[i][val] > 0) {
                return i;
            }
        }
        return -1;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

