public class Solution {
    public int minPathCost(int[][] grid, int[][] moveCost) {
        int m = grid.length;
        int n = grid[0].length;
        for (int i = m - 2; i >= 0; --i) {
            for (int j = 0; j < n; ++j) {
                int minCost = Integer.MAX_VALUE;
                for (int k = 0; k < n; ++k)
                    minCost = Math.min(minCost, moveCost[grid[i][j]][k] + grid[i + 1][k]);
