public class Solution {
    public int maximumsSplicedArray(int[] nums1, int[] nums2) {
        int n = nums1.length;
        long sum1 = 0, sum2 = 0;
        for (int i = 0; i < n; i++) {
            sum1 += nums1[i];
            sum2 += nums2[i];
        }

        if (sum1 >= sum2) {
            return helper(nums1, nums2);
        } else {
            return helper(nums2, nums1);
        }
    }

    private int helper(int[] nums1, int[] nums2) {
        int n = nums1.length;
        long maxSoFar = 0, minSoFar = 0;
        long maxEndingHere = 0, minEndingHere = 0;

        for (int i = 0; i < n; i++) {
            maxEndingHere += nums2[i] - nums1[i];
            if (maxEndingHere > maxSoFar) {
                maxSoFar = maxEndingHere;
            }
            if (maxEndingHere < 0) {
                maxEndingHere = 0;
            }

            minEndingHere += nums1[i] - nums2[i];
            if (minEndingHere < minSoFar) {
                minSoFar = minEndingHere;
            }
            if (minEndingHere > 0) {
                minEndingHere = 0;
            }
        }

        return (int)(Math.max(maxSoFar, -minSoFar) + sum(nums1));
    }

    private long sum(int[] nums) {
        long sum = 0;
        for (int num : nums) {
            sum += num;
        }
