        int xorNbr = nums[blockedNode] ^ xorSrc;
        int xorRemain = nums[0] ^ xorNbr ^ xorSrc;
        minScore = Math.min(minScore, Math.max(xorNbr, Math.max(xorSrc, xorRemain)) - Math.min(xorNbr, Math.min(xorSrc, xorRemain)));
    }
}

