// #Medium #String #Hash_Table #Greedy #2022_08_24_Time_26_ms_(100.00%)_Space_54.8_MB_(100.00%)
public class Solution {
    public String largestPalindromic(String num) {
        Map<Character, Integer> map = new HashMap<>();
        for (char c : num.toCharArray()) {
            map.put(c, map.getOrDefault(c, 0) + 1);
        }

        char[] res = new char[num.length()];
        int idx = 0;
        boolean hasOdd = false;
        for (Map.Entry<Character, Integer> entry : map.entrySet()) {
            if (entry.getValue() % 2 == 1 && !hasOdd) {
                hasOdd = true;
                res[idx++] = entry.getKey();
            }
            for (int i = 0; i < entry.getValue() / 2; i++) {
                res[idx++] = entry.getKey();
            }
        }

        Arrays.sort(res, 0, idx);
        reverse(res, 0, idx - 1);

        if (!hasOdd) {
            return new String(res, 0, idx).substring(1);
        } else {
            for (int i = 0; i < idx / 2; i++) {
                char temp = res[i];
                res[i] = res[idx - 1 - i];
                res[idx - 1 - i] = temp;
            }
            return new String(res, 0, idx);
        }
    }

    private void reverse(char[] arr, int start, int end) {
        while (start < end) {
            char temp = arr[start];
            arr[start++] = arr[end];
            arr[end--] = temp;
        }
    }
}

