public class Solution {
    public int maximumGroups(int[] grades) {
        int n = grades.length;
        int left = 1, right = n;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (canForm(mid, grades)) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return right;
    }

    private boolean canForm(int k, int[] grades) {
        long sum = 0;
        for (int i = 0; i < k; i++) {
            sum += (long)(i + 1) * (i + 2) / 2;
        }
        long totalSum = 0;
        for (int grade : grades) {
            totalSum += grade;
        }
        return totalSum >= sum;
    }
}

