// #Hard #Depth_First_Search #Graph #Topological_Sort
// #2022_08_14_Time_37_ms_(90.19%)_Space_102.8_MB_(72.92%)
public class Solution {
    public int longestCycle(int[] edges) {
        int n = edges.length;
        boolean[] visited = new boolean[n];
        int[] distToNode = new int[n];
        Arrays.fill(distToNode, -1);
        int res = -1;

        for (int i = 0; i < n; ++i) {
            if (!visited[i]) {
                dfs(edges, visited, distToNode, i, 0, res);
            }
        }

        return res;
    }

    private void dfs(int[] edges, boolean[] visited, int[] distToNode, int node, int distance, int res) {
        if (node != -1) {
            if (!visited[node]) {
                visited[node] = true;
                distToNode[node] = distance;

                dfs(edges, visited, distToNode, edges[node], distance + 1, res);
            } else if (distToNode[node] >= 0) {
                res = Math.max(res, distance - distToNode[node]);
            }
        }
    }
}

