public class Solution {
    public int maximumRows(int[][] matrix, int numSelect) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[] rowMask = new int[m];

        // Create a mask for each row
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == 1) {
                    rowMask[i] |= (1 << j);
                }
            }
        }

        int[] dp = new int[1 << n];
        for (int i = 0; i < m; i++) {
            for (int mask = 0; mask < (1 << n); mask++) {
                if ((rowMask[i] & mask) == rowMask[i]) {
                    dp[mask]++;
                }
            }
        }

        int[] maxRows = new int[numSelect + 1];
        for (int i = 0; i <= numSelect; i++) {
            for (int mask = 0; mask < (1 << n); mask++) {
                if (Integer.bitCount(mask) == i) {
                    for (int subMask = mask; ; subMask = (subMask - 1) & mask) {
                        maxRows[i] = Math.max(maxRows[i], dp[subMask]);
                        if (subMask == 0) break;
                    }
                }
            }
        }

        return maxRows[numSelect];
    }
}

