public class Solution {
    public int maximumXOR(int[] nums) {
        int mask = 0;
        int result = 0;

        // iterate over each bit position from most significant to least
        for (int i = 30; i >= 0; i--) {
            mask |= (1 << i);

            int tempResult = result | (1 << i);
            int prefixCount = 0;

            // count the number of prefixes that match 'tempResult'
            for (int num : nums) {
                if ((num & mask) == tempResult) {
                    prefixCount++;
                }
            }

            // if there are at least two prefixes matching 'tempResult', 
            // then we can get a larger XOR result
            if (prefixCount >= 2) {
                result = tempResult;
            }
        }

        return result;
    }
}

