public class Solution {
    public int[] smallestTrimmedNumbers(String[] nums, int[][] queries) {
        List<int[]> list = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) {
            list.add(new int[]{Integer.parseInt(nums[i]), i});
        }

        int[] res = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int k = queries[i][0], trim = queries[i][1];
            Collections.sort(list, (a, b) -> a[0] / (int) Math.pow(10, nums[0].length() - trim) == 
                                            b[0] / (int) Math.pow(10, nums[0].length() - trim) ? 
                                            Integer.compare(a[1], b[1]) : 
                                            Integer.compare(a[0] / (int) Math.pow(10, nums[0].length() - trim), 
                                                            b[0] / (int) Math.pow(10, nums[0].length() - trim)));
            res[i] = list.get(k - 1)[1];
        }
        return res;
    }
}

