public class Solution {
    public int longestSubsequence(String s, int k) {
        long num = 0;
        int n = s.length();
        int res = 0;

        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '1') {
                num = num * 2 + 1;
            } else {
                num = num * 2;
            }

            while (num > k && res > 0) {
                num /= 2;
                res--;
            }

            if (num <= k) {
                res++;
            }
        }

        return res;
    }
}

