public class Solution {
    public int countSubarrays(int[] nums, int k) {
        Map<Integer, Integer> map = new HashMap<>();
        map.put(0, 1);
        int sum = 0, res = 0;

        for (int num : nums) {
            if (num < k) sum--;
            else if (num > k) sum++;

            res += map.getOrDefault(sum, 0) + map.getOrDefault(sum - 1, 0);
            map.put(sum, map.getOrDefault(sum, 0) + 1);
        }

        return res;
    }
