public class Solution {
    public int hardestWorker(int n, int[][] logs) {
        int maxTime = 0;
        int id = -1;

        int prevTime = 0;
        for (int[] log : logs) {
            int time = log[1] - prevTime;
            if (time > maxTime) {
                maxTime = time;
                id = log[0];
            } else if (time == maxTime && log[0] < id) {
                id = log[0];
            }
            prevTime = log[1];
        }

        return id;
    }
}

