public class Solution {
    public int longestSubarray(int[] nums) {
        int n = nums.length;
        int maxVal = 0, maxLength = 0, currLength = 0, prevAnd = -1;

        for (int num : nums) {
            maxVal |= num;
        }

        for (int i = 0; i < n; i++) {
            if (nums[i] == maxVal) {
                currLength++;
            } else if (prevAnd != -1) {
                maxLength = Math.max(maxLength, currLength);
                currLength = 0;
                prevAnd = -1;
            }

            int and = nums[i];
            for (int j = i + 1; j < n && (and & maxVal) == maxVal; j++) {
                and &= nums[j];
                if ((and & maxVal) != maxVal) break;

                currLength++;
                prevAnd = and;
            }
        }

        return Math.max(maxLength, currLength);
    }
}

