import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public long numberOfPairs(int[] nums1, int[] nums2, int diff) {
        Integer[] indices = new Integer[nums1.length];
        for (int i = 0; i < nums1.length; i++) {
            indices[i] = i;
        }

        Arrays.sort(indices, Comparator.comparingInt(i -> nums1[i] - nums2[i]));

        long count = 0;
        int left = 0;
        for (int right = 0; right < nums1.length; right++) {
            while (left < right && nums1[indices[right]] - nums2[indices[right]] > nums1[indices[left]] - nums2[indices[left]] + diff) {
                left++;
            }
            count += right - left;
        }

        return count;
    }
}

