// #Hard #Array #Sorting #Greedy #2022_12_14_Time_57_ms_(87.86%)_Space_59.7_MB_(93.46%)
public class Solution {
    public long makeSimilar(int[] nums, int[] target) {
        int n = nums.length;
        int[] evenNums = new int[n];
        int[] oddNums = new int[n];
        int[] evenTarget = new int[n];
        int[] oddTarget = new int[n];

        int e = 0, o = 0;

        for (int i = 0; i < n; ++i) {
            if ((nums[i] & 1) == 1) {
                oddNums[o++] = nums[i];
            } else {
                evenNums[e++] = nums[i];
            }

            if ((target[i] & 1) == 1) {
                oddTarget[o - 1] = target[i];
            } else {
                evenTarget[e - 1] = target[i];
            }
        }

        Arrays.sort(evenNums, 0, e);
        Arrays.sort(oddNums, 0, o);
        Arrays.sort(evenTarget, 0, e);
        Arrays.sort(oddTarget, 0, o);

        long res = 0;
        for (int i = 0; i < e; ++i) {
            if (evenNums[i] != evenTarget[i]) res += Math.abs(evenNums[i] - evenTarget[i]) / 2;
        }

        for (int i = 0; i < o; ++i) {
            if (oddNums[i] != oddTarget[i]) res += Math.abs(oddNums[i] - oddTarget[i]) / 2;
        }

        return res;
    }
}

