import java.util.Arrays;
import java.util.List;

public class Solution {
    public long minimumTotalDistance(List<Integer> robot, int[][] f) {
        // sort factories :
        // 1. move all factories with 0-capacity to the end
        // 2. sort everything else by x-position in asc order
        Arrays.sort(f, (a, b) -> a[1] == 0 && b[1] != 0 ? 1 : a[1] != 0 && b[1] == 0 ? -1 : Integer.compare(a[0], b[0]));

        // Sort robots by x-position in asc order
        int[] r = new int[robot.size()];
        for (int i = 0; i < robot.size(); i++) {
            r[i] = robot.get(i);
        }
        Arrays.sort(r);

        long res = 0;
        int j = 0, k = f.length - 1;

        // As we don't know the implementation of the List that is passed, it is better to map it to
        // an array explicitly
        for (int i = r.length - 1; i >= 0 && k >= 0; i--) {
            while (j < f.length && f[j][1] == 0) j++;
            if (f[k][0] > r[i]) {
                res += Math.abs(f[k--][0] - r[i]);
            } else if (f[j][0] < r[i]) {
                res += Math.abs(f[j++][0] - r[i]);
            } else {
                int cost1 = Math.abs(f[k--][0] - r[i]), cost2 = Math.abs(f[j++][0] - r[i]);
                res += Math.min(cost1, cost2);
            }
        }

        return res;
    }
}

