// #Easy #String #Math #2022_10_24_Time_0_ms_(100.00%)_Space_40.3_MB_(91.71%)
public class Solution {
    public int totalDaysTogether(String arriveAlice, String leaveAlice, String arriveBob, String leaveBob) {
        int[] days = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        return Math.max(0, helper(days, leaveAlice) - helper(days, arriveAlice) + 
                         Math.min(helper(days, leaveBob), helper(days, leaveAlice)) - 
                         Math.max(helper(days, arriveBob), helper(days, arriveAlice)));
    }

    private int helper(int[] days, String date) {
        int month = Integer.parseInt(date.substring(0, 2));
        int day = Integer.parseInt(date.substring(3));
        for (int i = 1; i < month; i++) {
            day += days[i - 1];
        }
        return day;
    }
}

