        dfs(root, set);

        int n = queries.length;
        int[][] res = new int[n][2];

        for (int i = 0; i < n; i++) {
            Integer lower = set.floor(queries[i]);
            Integer higher = set.ceiling(queries[i]);

            if (lower == null) {
                res[i][0] = -1;
            } else {
                res[i][0] = lower;
            }

            if (higher == null) {
                res[i][1] = -1;
            } else {
                res[i][1] = higher;
            }
        }

        return res;
    }

    private void dfs(TreeNode node, TreeSet<Integer> set) {
        if (node == null) {
            return;
        }

        set.add(node.val);
        dfs(node.left, set);
        dfs(node.right, set);
    }
}

