// #Hard #Array #Dynamic_Programming #Matrix #2022_12_07_Time_70_ms_(99.20%)_Space_84.5_MB_(87.93%)
import java.util.Arrays;
public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numberOfPaths(int[][] grid, int k) {
        int m = grid.length, n = grid[0].length;
        int[][] dp = new int[m][n];
        dp[0][0] = 1;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i > 0) {
                    dp[i][j] += dp[i - 1][j];
                    dp[i][j] %= MOD;
                }
                if (j > 0) {
                    dp[i][j] += dp[i][j - 1];
                    dp[i][j] %= MOD;
                }
            }
        }

        int[][][] ways = new int[m + 1][n + 1][k];
        ways[0][0][grid[0][0] % k]++;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) continue;
                int sum = grid[i][j];
                if (i > 0) {
                    for (int l = 0; l < k; l++) {
                        ways[i][j][(l + sum) % k] += ways[i - 1][j][l];
                        ways[i][j][(l + sum) % k] %= MOD;
                    }
                }
                if (j > 0) {
                    for (int l = 0; l < k; l++) {
                        ways[i][j][(l + sum) % k] += ways[i][j - 1][l];
                        ways[i][j][(l + sum) % k] %= MOD;
                    }
                }
            }
        }

        return ways[m - 1][n - 1][0];
    }
}

