import java.util.Arrays;

public class Solution {
    public long dividePlayers(int[] skill) {
        Arrays.sort(skill);
        int n = skill.length;
        int targetSum = skill[0] + skill[n - 1];
        long sumChemistry = (long)skill[0] * skill[n - 1];

        for (int i = 1; i < n / 2; i++) {
            if (skill[i] + skill[n - 1 - i] != targetSum) {
                return -1;
            }
            sumChemistry += (long)skill[i] * skill[n - 1 - i];
        }

        return sumChemistry;
    }
}

