import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int componentValue(int[] nums, int[][] edges) {
        int n = nums.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        long sum = 0;
        for (int num : nums) {
            sum += num;
        }

        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            graph[u].add(v);
            graph[v].add(u);
        }

        if (sum % n == 0 && dfs(graph, new boolean[n], nums, sum / n, 0, -1)) {
            return n - 1;
        }

        for (int i = n; i >= 2; i--) {
            if (sum % i != 0) continue;
            if (dfs(graph, new boolean[n], nums, sum / i, 0, -1)) {
                return n - i;
            }
        }

        return 0;
    }

    private boolean dfs(List<Integer>[] graph, boolean[] visited, int[] nums, long target, int u, int p) {
        visited[u] = true;
        long sum = nums[u];

        for (int v : graph[u]) {
            if (v == p || visited[v]) continue;
            sum += dfs(graph, visited, nums, target, v, u);
        }

        return sum % target == 0;
    }
}

