public class Solution {
    public long makeIntegerBeautiful(long n, int target) {
        long x = 0;
        long multiplier = 1;
        while (true) {
            long digitSum = getDigitSum(n + x);
            if (digitSum <= target) {
                return x;
            }
            long lastDigit = (n + x) % 10;
            x += (10 - lastDigit) * multiplier;
            n /= 10;
            multiplier *= 10;
        }
    }

    private int getDigitSum(long num) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        return sum;
    }
}

