// #Hard #Array #Sorting #Heap_Priority_Queue #2022_10_23_Time_124_ms_(72.79%)_Space_107_MB_(80.70%)
public class Solution {
    public int mostBooked(int n, int[][] meetings) {
        Arrays.sort(meetings, (a, b) -> a[0] - b[0]);

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[1] == b[1] ? a[0] - b[0] : a[1] - b[1]);

        int[] count = new int[n];
        for (int i = 0; i < n; i++) {
            pq.offer(new int[]{i, meetings[i][0]});
            count[i]++;
        }

        for (int i = n; i < meetings.length; i++) {
            int[] top = pq.poll();
            if (meetings[i][0] >= top[1]) {
                pq.offer(new int[]{top[0], meetings[i][0]});
                count[top[0]]++;
            } else {
                int[] next = pq.poll();
                pq.offer(top);
                pq.offer(new int[]{next[0], Math.max(next[1], meetings[i][0]) + (meetings[i][1] - meetings[i][0])});
                count[next[0]]++;
            }
        }

        int maxCount = 0;
        for (int i = 1; i < n; i++) {
            if (count[maxCount] < count[i]) {
                maxCount = i;
            }
        }

        return maxCount;
    }
}

