import java.util.ArrayList;
import java.util.List;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int[] productQueries(int n, int[][] queries) {
        List<Integer> powers = new ArrayList<>();
        for (int i = 0; n > 0; i++, n >>= 1) {
            if ((n & 1) == 1) {
                powers.add(1 << i);
            }
        }

        int[] prefixProduct = new int[powers.size() + 1];
        prefixProduct[0] = 1;
        for (int i = 1; i <= powers.size(); i++) {
            prefixProduct[i] = (int) ((long) prefixProduct[i - 1] * powers.get(i - 1) % MOD);
        }

        int[] answers = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int left = queries[i][0], right = queries[i][1];
            long product = (long) prefixProduct[right + 1] * pow(prefixProduct[left], MOD - 2, MOD);
            answers[i] = (int) (product % MOD);
        }

        return answers;
    }

    private int pow(int base, int exponent, int mod) {
        if (exponent == 0) {
            return 1;
        }
        long result = pow(base, exponent / 2, mod);
        result = (result * result) % mod;
        if ((exponent & 1) == 1) {
            result = (result * base) % mod;
        }
        return (int) result;
    }
}

