public class Solution {
    public long minimumMoney(int[][] transactions) {
        int n = transactions.length;
        Arrays.sort(transactions, (a, b) -> a[1] - b[1]);

        long money = 0;
        for (int i = n - 1; i >= 0; --i) {
            if (money < transactions[i][0]) {
                money += transactions[i][0] - money + Math.max(0, transactions[i][0] - transactions[i][1]);
            } else {
                money -= transactions[i][1];
            }
        }

        return money;
    }
}

