// #Easy #String #Hash_Table #Counting #2022_11_18_Time_1_ms_(75.41%)_Space_41.9_MB_(50.90%)
public class Solution {
    public boolean canEqualFrequency(String word) {
        Map<Character, Integer> freqMap = new HashMap<>();

        for (char c : word.toCharArray()) {
            freqMap.put(c, freqMap.getOrDefault(c, 0) + 1);
        }

        int maxFreq = 0;
        for (int freq : freqMap.values()) {
            if (freq > maxFreq) {
                maxFreq = freq;
            }
        }

        if (maxFreq == 1) return true;

        Map<Character, Integer> newFreqMap = new HashMap<>();
        boolean found = false;

        for (char c : word.toCharArray()) {
            int newFreq = freqMap.get(c) - 1;
            if (newFreq > 0) {
                newFreqMap.put(c, newFreq);
            }

            if (!found && newFreq == maxFreq - 1) {
                found = true;
            } else if (found && newFreq != maxFreq - 1) {
                return false;
            }
        }

        return true;
    }
}

