public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int countGoodStrings(int low, int high, int zero, int one) {
        int[] dp = new int[high + 1];
        dp[0] = 1;

        for (int i = Math.min(zero, one); i <= high; i++) {
            if (i >= zero) {
                dp[i] += dp[i - zero];
            }
            if (i >= one) {
                dp[i] += dp[i - one];
            }
            dp[i] %= MOD;
        }

        int res = 0;
        for (int i = low; i <= high; i++) {
            res += dp[i];
            res %= MOD;
        }

        return res;
    }
}

