    public int countPalindromes(String s) {
        long[][] dp = new long[10][s.length()];

        // Initialize single digit counts
        for (int i = 0; i < 10; i++) {
            dp[i][0] = s.charAt(0) - '0' == i ? 1 : 0;
        }

        // Calculate counts of two-digit palindromes
        long[] count2 = new long[100];
        for (int i = 0; i < s.length() - 1; i++) {
            int a = s.charAt(i) - '0';
            int b = s.charAt(i + 1) - '0';
            if (a == b) {
                count2[a * 10 + b]++;
            }
        }

        // Calculate counts of three-digit palindromes
        long[] count3 = new long[100];
        for (int i = 0; i < s.length() - 2; i++) {
            int a = s.charAt(i) - '0';
            int b = s.charAt(i + 1) - '0';
            int c = s.charAt(i + 2) - '0';
            if (a == c) {
                count3[a * 10 + b]++;
            }
        }

        // Calculate counts of four-digit palindromes
        long[] count4 = new long[100];
        for (int i = 0; i < s.length() - 3; i++) {
            int a = s.charAt(i) - '0';
            int b = s.charAt(i + 1) - '0';
            int c = s.charAt(i + 2) - '0';
            int d = s.charAt(i + 3) - '0';
            if (a == d && b == c) {
                count4[a * 10 + b]++;
            }
        }

        // Calculate counts of five-digit palindromes
        long[] count5 = new long[100];
        for (int i = 0; i < s.length() - 4; i++) {
