// #Hard #Array #Greedy #Heap_Priority_Queue #Ordered_Set
// #2022_04_19_Time_104_ms_(88.83%)_Space_58.3_MB_(91.85%)
import java.util.PriorityQueue;

public class Solution {
    public int minimumDeviation(int[] nums) {
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>((a, b) -> b - a);

        for (int num : nums) {
            if (num % 2 == 1) {
                num *= 2;
            }
            maxHeap.offer(num);
        }

        int minDeviation = Integer.MAX_VALUE;
        int minVal = maxHeap.peek();

        while (!maxHeap.isEmpty()) {
            int maxVal = maxHeap.poll();
            minDeviation = Math.min(minDeviation, maxVal - minVal);

            if (maxVal % 2 == 0) {
                int nextMaxVal = maxVal / 2;
                maxHeap.offer(nextMaxVal);
                if (nextMaxVal < minVal) {
                    minVal = nextMaxVal;
                }
            } else {
                break;
            }
        }

        return minDeviation;
    }
}

