public class Solution {
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    private static final int INF = (int) 1e9;
    private int m, n, introvertsCount, extrovertsCount;

    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        this.m = m;
        this.n = n;
        this.introvertsCount = introvertsCount;
        this.extrovertsCount = extrovertsCount;
        return dfs(0, 0, 0, 0);
    }

    private int dfs(int x, int y, int introvertsLeft, int extrovertsLeft) {
        if (introvertsLeft < 0 || extrovertsLeft < 0) {
            return -INF;
        }
        if (x == m) {
            return dfs(0, y + 1, introvertsLeft, extrovertsLeft);
        }
        if (y == n) {
            return 0;
        }

        int maxHappiness = -INF;

        // Try not placing anyone
        maxHappiness = Math.max(maxHappiness, dfs(x + 1, y, introvertsLeft, extrovertsLeft));

        // Try placing an introvert
        if (introvertsLeft > 0) {
            int happiness = 120;
            for (int[] direction : DIRECTIONS) {
                int nx = x + direction[0];
                int ny = y + direction[1];
                if (nx >= 0 && nx < m && ny >= 0 && ny < n) {
                    // Simulate placing an introvert at the current position
                    happiness -= 30;
                }
            }
            maxHappiness = Math.max(maxHappiness, dfs(x + 1, y, introvertsLeft - 1, extrovertsLeft) + happiness);
        }

        // Try placing an extrovert
        if (extrovertsLeft > 0) {
            int happiness = 40;
            for (int[] direction : DIRECTIONS) {
                int nx = x + direction[0];
                int ny = y + direction[1];
                if (nx >= 0 && nx < m && ny >= 0 && ny < n) {
                    // Simulate placing an extrovert at the current position
                    happiness += 20;
                }
            }
            maxHappiness = Math.max(maxHappiness, dfs(x + 1, y, introvertsLeft, extrovertsLeft - 1) + happiness);
        }

        return maxHappiness;
    }
