public class Solution {
    public boolean canDistribute(int[] nums, int[] quantity) {
        Arrays.sort(quantity);
        Map<Integer, Integer> count = new HashMap<>();
        for (int num : nums) {
            count.put(num, count.getOrDefault(num, 0) + 1);
        }

        int n = quantity.length;
        boolean[] used = new boolean[n];
        return dfs(count, quantity, 0, used);
    }

    private boolean dfs(Map<Integer, Integer> count, int[] quantity, int index, boolean[] used) {
        if (index == quantity.length) {
            return true;
        }

        for (int num : count.keySet()) {
            if (count.get(num) >= quantity[index]) {
                count.put(num, count.get(num) - quantity[index]);
                if (dfs(count, quantity, index + 1, used)) {
                    return true;
                }
                count.put(num, count.get(num) + quantity[index]);
            }
        }

        return false;
    }
}

