import com_github_leetcode.ListNode;

public class Solution {
    public ListNode mergeInBetween(ListNode list1, int a, int b, ListNode list2) {
        // find the node before the start of the range to be removed
        ListNode dummy = new ListNode(0);
        dummy.next = list1;
        ListNode prev = dummy;
        for (int i = 0; i < a; i++) {
            prev = prev.next;
        }

        // find the node after the end of the range to be removed
        ListNode nextNode = prev;
        for (int i = 0; i <= b - a + 1; i++) {
            nextNode = nextNode.next;
        }

        // find the last node of list2
        ListNode lastNodeOfList2 = list2;
        while (lastNodeOfList2.next != null) {
            lastNodeOfList2 = lastNodeOfList2.next;
        }

        // connect the nodes
        prev.next = list2;
        lastNodeOfList2.next = nextNode;

        return dummy.next;
    }
}

