public class Solution {
    public int minimumJumps(int[] forbidden, int a, int b, int x) {
        Set<Integer> set = new HashSet<>();
        for (int num : forbidden) {
            set.add(num);
        }
        Queue<Pair> queue = new LinkedList<>();
        boolean[] visited = new boolean[20001];
        queue.offer(new Pair(0, false));
        visited[0] = true;
        int step = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                Pair pair = queue.poll();
                if (pair.i == x) return step;
                if (pair.b) {
                    int next = pair.i - b;
                    if (next >= 0 && !set.contains(next) && !visited[next]) {
                        visited[next] = true;
                        queue.offer(new Pair(next, false));
                    }
                } else {
                    int next1 = pair.i + a;
                    if (!set.contains(next1) && !visited[next1]) {
                        visited[next1] = true;
                        queue.offer(new Pair(next1, true));
                    }
                    int next2 = pair.i - b;
                    if (next2 >= 0 && !set.contains(next2) && !visited[next2]) {
                        visited[next2] = true;
                        queue.offer(new Pair(next2, false));
                    }
                }
            }
            step++;
        }
        return -1;
    }

