public class Solution {
    public int waysToMakeFair(int[] nums) {
        int n = nums.length;
        int oddSum = 0, evenSum = 0;

        // Calculate initial sums of odd and even indexed elements
        for (int i = 0; i < n; i++) {
            if ((i & 1) == 1) {
                oddSum += nums[i];
            } else {
                evenSum += nums[i];
            }
        }

        int res = 0;

        // Check each index
        for (int i = 0; i < n; i++) {
            if ((i & 1) == 1) {
                oddSum -= nums[i];
            } else {
                evenSum -= nums[i];
            }

            // If removing current element makes the array fair, increment result
            if (evenSum - oddSum + (i > 0 ? nums[0] : 0) == 0 || 
                i < n - 1 && evenSum + nums[n-1] - oddSum == 0) {
                res++;
            }
        }

        return res;
    }
}

