            } else if (n - i == 4) {
                result.append(sb.substring(i, i + 2)).append('-');
                result.append(sb.substring(i + 2));
                break;
            }
            result.append(sb.substring(i, Math.min(n, i + 3))).append('-');
            i += 3;
        }

        return result.toString().replaceAll("-$", "");
    }
}

