public class Solution {
    public int minMoves(int[] nums, int limit) {
        int n = nums.length;
        int[] count = new int[limit * 2 + 1];

        for (int i = 0; i < n / 2; i++) {
            int a = Math.min(nums[i], nums[n - 1 - i]);
            int b = Math.max(nums[i], nums[n - 1 - i]);

            count[2] += 2;
            count[a + 1] -= 1;
            count[b + limit + 1] -= 1;
            count[a + b] += 1;
        }

