public class Solution {
    public int[] maxSumOfThreeSubarrays(int[] nums, int k) {
        int n = nums.length;
        int[] sum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            sum[i + 1] = sum[i] + nums[i];
        }

        int maxSum = Integer.MIN_VALUE, left = -1, mid = -1, right = -1;
        for (int i = 0; i <= n - k; i++) {
            for (int j = i + k; j <= n - k; j++) {
                for (int p = j + k; p <= n - k; p++) {
                    int s = sum[i + k] - sum[i] + sum[j + k] - sum[j] + sum[p + k] - sum[p];
