public class Solution {
    public List<Integer> fallingSquares(int[][] positions) {
        Set<Integer> points = new TreeSet<>();
        for (int[] pos : positions) {
            points.add(pos[0]);
            points.add(pos[0] + pos[1]);
        }

        List<Integer> list = new ArrayList<>(points);
        Collections.sort(list);

        int n = list.size();
        int[] map = new int[n];
        for (int i = 0; i < n; i++) {
            map[i] = list.get(i);
        }

        int[] heights = new int[n];
        List<Integer> ans = new ArrayList<>();
        int max = 0;

        for (int[] pos : positions) {
            int x1 = Collections.binarySearch(list, pos[0]);
            int x2 = Collections.binarySearch(list, pos[0] + pos[1]);

            int currMax = 0;
            for (int i = x1; i < x2; i++) {
                currMax = Math.max(currMax, heights[i]);
            }

            currMax += pos[1];
            for (int i = x1; i < x2; i++) {
                heights[i] = currMax;
            }

            max = Math.max(max, currMax);
            ans.add(max);
        }

        return ans;
    }
}

