public class Solution {
    public String solveEquation(String equation) {
        int pos = equation.indexOf('=');
        int leftX = count(equation.substring(0, pos));
        int rightX = count(equation.substring(pos + 1));

        if (leftX == rightX) {
            return leftX == 0 ? "Infinite solutions" : "x=" + (rightX / leftX);
        } else {
            return "No solution";
        }
    }

