        int res = 0, sign = 1, num = 0;
        for (int i = 0; i < s.length(); ++i) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                num = num * 10 + c - '0';
            } else if (c == '+' || c == '-') {
                res += sign * (num != 0 ? num : 1);
                sign = c == '+' ? 1 : -1;
                num = 0;
            }
        }
        return res + sign * (num != 0 ? num : 1);
    }
}

