public class Solution {
    public List<Double> averageOfLevels(TreeNode root) {
        List<Double> result = new ArrayList<>();
        if (root == null) return result;

        Map<Integer, double[]> map = new HashMap<>();
        dfs(root, 0, map);

        for (double[] arr : map.values()) {
            result.add(arr[0] / arr[1]);
        }

        return result;
    }

    private void dfs(TreeNode node, int level, Map<Integer, double[]> map) {
        if (node == null) return;

        map.computeIfAbsent(level, k -> new double[]{0.0, 0});
        double[] arr = map.get(level);
        arr[0] += node.val;
        arr[1]++;

        dfs(node.left, level + 1, map);
        dfs(node.right, level + 1, map);
    }
}

