public class Solution {
    public List<List<String>> printTree(TreeNode root) {
        int height = getHeight(root);
        int rows = height + 1;
        int cols = (int)Math.pow(2, height) - 1;

        List<List<String>> res = new ArrayList<>();
        for(int i = 0; i < rows; i++) {
            List<String> row = new ArrayList<>();
            for(int j = 0; j < cols; j++) {
                row.add("");
            }
            res.add(row);
        }

        dfs(root, res, 0, (cols - 1) / 2, height);

        return res;
    }

    private int getHeight(TreeNode node) {
        if(node == null) {
            return 0;
        } else {
            return Math.max(getHeight(node.left), getHeight(node.right)) + 1;
        }
    }

    private void dfs(TreeNode node, List<List<String>> res, int row, int col, int height) {
        if(node == null) {
            return;
        }

        res.get(row).set(col, String.valueOf(node.val));

        dfs(node.left, res, row + 1, col - (int)Math.pow(2, height - row - 1), height);
        dfs(node.right, res, row + 1, col + (int)Math.pow(2, height - row - 1), height);
    }
}

