public class Solution {
    public int minHeightShelves(int[][] books, int shelfWidth) {
        return helper(books, 0, shelfWidth, new Integer[books.length]);
    }

    private int helper(int[][] books, int index, int width, Integer[] memo) {
        if (index == books.length)
            return 0;
        if (memo[index] != null)
            return memo[index];
        int maxH = 0, currW = 0, res = Integer.MAX_VALUE;
        for (int i = index; i < books.length; i++) {
            if (currW + books[i][0] > width)
                break;
            currW += books[i][0];
            maxH = Math.max(maxH, books[i][1]);
            int next = helper(books, i + 1, width, memo);
            res = Math.min(res, maxH + next);
        }
        return memo[index] = res;
    }
}

