public class Solution {
    public int movesToMakeZigzag(int[] nums) {
        int n = nums.length;
        int res1 = 0, res2 = 0;

        // make even-indexed elements greater than adjacent ones
        for (int i = 0; i < n; i++) {
            if ((i % 2 == 0 && (i > 0 && nums[i] >= nums[i - 1] || i + 1 < n && nums[i] >= nums[i + 1])) 
                || (i % 2 != 0 && (i > 0 && nums[i] <= nums[i - 1] || i + 1 < n && nums[i] <= nums[i + 1]))) {
                if (i > 0) res1 += Math.max(0, nums[i] - (nums[i - 1] - 1));
                if (i + 1 < n) res1 += Math.max(0, nums[i] - (nums[i + 1] - 1));
            }
        }

        // make odd-indexed elements greater than adjacent ones
        for (int i = 0; i < n; i++) {
            if ((i % 2 != 0 && (i > 0 && nums[i] >= nums[i - 1] || i + 1 < n && nums[i] >= nums[i + 1])) 
                || (i % 2 == 0 && (i > 0 && nums[i] <= nums[i - 1] || i + 1 < n && nums[i] <= nums[i + 1]))) {
                if (i > 0) res2 += Math.max(0, nums[i] - (nums[i - 1] - 1));
                if (i + 1 < n) res2 += Math.max(0, nums[i] - (nums[i + 1] - 1));
            }
        }

        return Math.min(res1, res2);
    }
}

