public class Solution {
    public String lastSubstring(String s) {
        int n = s.length();
        char[] chars = s.toCharArray();
        int maxIndex = 0;

        for (int i = 1; i < n; i++) {
            if (chars[i] > chars[maxIndex]) {
                maxIndex = i;
            } else if (chars[i] == chars[maxIndex]) {
                int j = i + 1, k = maxIndex + 1;
                while (j < n && k < n) {
                    if (chars[j] > chars[k]) {
                        maxIndex = i;
                        break;
                    } else if (chars[j] < chars[k]) {
                        break;
                    }
                    j++;
                    k++;
                }
            }
        }

        return s.substring(maxIndex);
    }
}

