                    count += wordMap.get(submask | (1 << (puzzle.charAt(0) - 'a')));
                }
                submask = (submask - 1) & mask;
            }
            if (wordMap.containsKey(1 << (puzzle.charAt(0) - 'a'))) {
                count += wordMap.get(1 << (puzzle.charAt(0) - 'a'));
            }
            result.add(count);
        }

