// #2023_06_01_Time_0_ms_(100.00%)_Space_43.4_MB_(8.40%)
import com_github_leetcode.TreeNode;
public class Solution {
    private int maxDepth = 0;
    private TreeNode result;

    public TreeNode lcaDeepestLeaves(TreeNode root) {
        dfs(root, 0);
        return result;
    }

    private int dfs(TreeNode node, int depth) {
        if (node == null) {
            return depth - 1;
        }
        maxDepth = Math.max(maxDepth, depth);
        int left = dfs(node.left, depth + 1);
        int right = dfs(node.right, depth + 1);

        if (left == maxDepth && right == maxDepth) {
            result = node;
        } else if (left > right) {
            result = findLCA(result, node.left);
        } else if (right > left) {
            result = findLCA(result, node.right);
        }
        return Math.max(left, right);
    }

    private TreeNode findLCA(TreeNode p, TreeNode q) {
        if (p == null || q == null) return null;
        if (p.val == q.val) return p;

        int left = findLCA(p.left, q);
        int right = findLCA(p.right, q);

        if (left != null && right != null) return p;
        else if (left != null) return left;
        else return right;
    }
}

