public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        Arrays.sort(sums);
        int[] ans = new int[n];
        for (int i = 0; i < n; ++i) {
            int[] cnt = new int[10001];
            for (int sum : sums)
                if (sum != 0)
                    cnt[sum]++;

