public class Solution {
    public int minStoneSum(int[] piles, int k) {
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());

        for (int pile : piles) {
            maxHeap.offer(pile);
        }

        while (k > 0) {
            int stones = maxHeap.poll();
            stones -= stones / 2;
            maxHeap.offer(stones);
            k--;
        }

        int sum = 0;
        while (!maxHeap.isEmpty()) {
            sum += maxHeap.poll();
        }

        return sum;
    }
}

