public class Solution {
    public int minimizeTheDifference(int[][] mat, int target) {
        TreeSet<Integer> set = new TreeSet<>();
        for (int[] row : mat) {
            Arrays.sort(row);
            if (set.isEmpty()) {
                for (int num : row) {
                    set.add(num);
                }
            } else {
                TreeSet<Integer> temp = new TreeSet<>();
                for (int num1 : set) {
                    for (int num2 : row) {
                        int sum = num1 + num2;
                        if (sum <= target * 2) {
                            temp.add(sum);
                        }
                    }
                }
                set = temp;
            }
        }

        Integer lower = set.floor(target);
        Integer higher = set.ceiling(target);

        return Math.min(Math.abs(lower - target), Math.abs(higher - target));
    }
}

