import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int[][] findFarmland(int[][] land) {
        if (land == null || land.length == 0) return new int[0][];

        int m = land.length, n = land[0].length;
        boolean[][] visited = new boolean[m][n];
        List<int[]> result = new ArrayList<>();

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (!visited[i][j] && land[i][j] == 1) {
                    int[] group = dfs(land, visited, i, j);
                    result.add(group);
                }
            }
        }

        return result.toArray(new int[result.size()][]);
    }

    private int[] dfs(int[][] land, boolean[][] visited, int x, int y) {
        if (x < 0 || x >= land.length || y < 0 || y >= land[0].length || visited[x][y] || land[x][y] == 0) return null;

        visited[x][y] = true;
        int[] leftTop = dfs(land, visited, x - 1, y);
        int[] rightBottom = dfs(land, visited, x + 1, y);
        int[] topRight = dfs(land, visited, x, y + 1);
        int[] bottomLeft = dfs(land, visited, x, y - 1);

        if (leftTop == null && rightBottom == null && topRight == null && bottomLeft == null) {
            return new int[]{x, y, x, y};
        } else {
            int leftX = Math.min(x, leftTop != null ? leftTop[0] : Integer.MAX_VALUE);
            int leftY = Math.min(y, leftTop != null ? leftTop[1] : Integer.MAX_VALUE);
            int rightX = Math.max(x, rightBottom != null ? rightBottom[2] : 0);
            int rightY = Math.max(y, topRight != null ? topRight[3] : 0);

            return new int[]{leftX, leftY, rightX, rightY};
        }
    }
}

