public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int firstDayBeenInAllRooms(int[] nextVisit) {
        int n = nextVisit.length;
        long[] dp = new long[n];

        for (int i = 1; i < n; i++) {
            if ((dp[i - 1] & 1) == 0) {
                dp[i] = (2 * dp[i - 1] + 1) % MOD;
            } else {
                int j = nextVisit[i - 1];
                long diff = dp[i - 1] - dp[j] + 1;
                if ((diff & 1) == 0) {
                    dp[i] = (2 * dp[i - 1]) % MOD;
                } else {
                    dp[i] = (2 * dp[i - 1] - diff + 1) % MOD;
                }
            }
        }

        return (int) dp[n - 1];
    }
}

