// #2022_05_16_Time_87_ms_(48.43%)_Space_145.9_MB_(64.15%)
import com_github_leetcode.TreeNode;
import java.util.ArrayDeque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Queue;

public class Solution {
    public TreeNode canMerge(List<TreeNode> trees) {
        Map<Integer, TreeNode> map = new HashMap<>();
        int min = Integer.MAX_VALUE;
        int max = Integer.MIN_VALUE;

        for (TreeNode tree : trees) {
            map.put(tree.val, tree);
            min = Math.min(min, tree.val);
            max = Math.max(max, tree.val);
        }

        TreeNode root = null;
        Queue<TreeNode> queue = new ArrayDeque<>();
        for (TreeNode tree : trees) {
            if (tree.left != null && !map.containsKey(tree.left.val)) return null;
            if (tree.right != null && !map.containsKey(tree.right.val)) return null;

            if (tree.val == min || tree.val == max) {
                root = tree;
            } else {
                queue.offer(tree);
            }
        }

        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();
            if (node.left != null && map.containsKey(node.left.val)) {
                TreeNode leftChild = map.get(node.left.val);
                node.left = leftChild;
                queue.remove(leftChild);
            }
            if (node.right != null && map.containsKey(node.right.val)) {
                TreeNode rightChild = map.get(node.right.val);
                node.right = rightChild;
                queue.remove(rightChild);
            }
        }

        return isValidBST(root) ? root : null;
    }

    private boolean isValidBST(TreeNode root, long min, long max) {
        if (root == null) return true;
        if (root.val <= min || root.val >= max) return false;
        return isValidBST(root.left, min, root.val) && isValidBST(root.right, root.val, max);
    }

    private boolean isValidBST(TreeNode root) {
        return isValidBST(root, Long.MIN_VALUE, Long.MAX_VALUE);
    }
}

