import java.util.HashMap;
import java.util.Map;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;
    private Map<String, Integer> memo;

    public int colorTheGrid(int m, int n) {
        memo = new HashMap<>();
        return dfs(m, n, "", -1);
    }

    private int dfs(int m, int n, String row, int lastColor) {
        if (row.length() == n) {
            if (m == 0) {
                return 1;
            }
            return dfs(m - 1, n, "", -1);
        }

        String key = m + "_" + n + "_" + row + "_" + lastColor;
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        int res = 0;
        for (int color = 0; color < 3; color++) {
            if (color != lastColor) {
                res += dfs(m, n, row + color, color);
                res %= MOD;
            }
        }

        memo.put(key, res);
        return res;
    }
}

