import java.util.*;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int countPaths(int n, int[][] roads) {
        List<int[]>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] road : roads) {
            graph[road[0]].add(new int[]{road[1], road[2]});
            graph[road[1]].add(new int[]{road[0], road[2]});
        }

        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[0] = 0;

        long[] ways = new long[n];
        ways[0] = 1;

        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));
        pq.offer(new int[]{0, 0});

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            if (curr[1] > dist[curr[0]]) continue;

            for (int[] neighbor : graph[curr[0]]) {
                long newDist = curr[1] + neighbor[1];
                if (newDist < dist[neighbor[0]]) {
                    dist[neighbor[0]] = newDist;
                    ways[neighbor[0]] = ways[curr[0]];
                    pq.offer(new int[]{neighbor[0], (int) newDist});
                } else if (newDist == dist[neighbor[0]]) {
                    ways[neighbor[0]] = (ways[neighbor[0]] + ways[curr[0]]) % MOD;
                }
            }
        }

        return (int) ways[n - 1];
    }
}

