public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int waysToBuildRooms(int[] prevRoom) {
        int n = prevRoom.length;
        List<Integer>[] graph = new ArrayList[n];

        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int i = 1; i < n; i++) {
            graph[prevRoom[i]].add(i);
        }

        long[] dp = new long[n];
        Arrays.fill(dp, -1);

        return (int) dfs(0, graph, dp);
    }

    private long dfs(int node, List<Integer>[] graph, long[] dp) {
        if (dp[node] != -1) {
            return dp[node];
        }

        long res = 1;
        for (int child : graph[node]) {
            res = res * (dfs(child, graph, dp) + 1) % MOD;
        }

        dp[node] = res;
        return res;
    }
}

