// #Medium #Array #Dynamic_Programming #2022_05_20_Time_42_ms_(95.45%)_Space_43_MB_(66.67%)
public class Solution {
    public int minSpaceWastedKResizing(int[] nums, int k) {
        int n = nums.length;
        long sum = 0;
        for (int num : nums) {
            sum += num;
        }

        long[][] dp = new long[n + 1][k + 2];
        for (long[] row : dp) {
            Arrays.fill(row, Long.MAX_VALUE);
        }
        dp[0][0] = 0;

        int max = 0;
        for (int i = 1; i <= n; i++) {
            max = Math.max(max, nums[i - 1]);
            long total = sum + max * (i - 1) - max;
            for (int j = 0; j <= k && j < i; j++) {
                dp[i][j + 1] = Math.min(dp[i][j + 1], dp[i - 1][j] + total);
                if (j > 0) {
                    dp[i][j] = Math.min(dp[i][j], dp[i - 1][j]);
                }
            }
        }

        long res = Long.MAX_VALUE;
        for (int j = 0; j <= k && j < n; j++) {
            res = Math.min(res, dp[n][j + 1] - sum);
        }
        return (int) res;
    }
}

