import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int minSessions(int[] tasks, int sessionTime) {
        Arrays.sort(tasks);
        reverseArray(tasks);

        int low = 1, high = tasks.length;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (!canFit(mid, tasks, sessionTime)) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }

        return low;
    }

    private boolean canFit(int sessions, int[] tasks, int sessionTime) {
        int[] timeLeft = new int[sessions];
        Arrays.fill(timeLeft, sessionTime);

        for (int task : tasks) {
            boolean foundSession = false;
            for (int i = 0; i < sessions; i++) {
                if (timeLeft[i] >= task) {
                    timeLeft[i] -= task;
                    foundSession = true;
                    break;
                }
            }

            if (!foundSession) return false;
        }

        return true;
    }

    private void reverseArray(int[] arr) {
        int left = 0, right = arr.length - 1;
        while (left < right) {
            int temp = arr[left];
            arr[left] = arr[right];
            arr[right] = temp;

            left++;
            right--;
        }
    }
}

