public class Solution {
    public long maxPoints(int[][] points) {
        int m = points.length;
        int n = points[0].length;

        long[] dp = new long[n];
        for (int i = 0; i < n; i++) {
            dp[i] = points[0][i];
        }

        for (int i = 1; i < m; i++) {
            long[] leftToRight = new long[n];
            long[] rightToLeft = new long[n];

            leftToRight[0] = dp[0];
            for (int j = 1; j < n; j++) {
                leftToRight[j] = Math.max(leftToRight[j - 1], dp[j]) + points[i][j];
            }

            rightToLeft[n - 1] = dp[n - 1];
            for (int j = n - 2; j >= 0; j--) {
                rightToLeft[j] = Math.max(rightToLeft[j + 1], dp[j]) + points[i][j];
            }

            for (int j = 0; j < n; j++) {
                dp[j] = Math.max(leftToRight[j], rightToLeft[j]);
            }
        }

        long maxPoints = Long.MIN_VALUE;
        for (long point : dp) {
            maxPoints = Math.max(maxPoints, point);
        }

        return maxPoints;
    }
}

