import java.util.*;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;
    private static final int MAX_PRIME = 30;

    public int numberOfGoodSubsets(int[] nums) {
        int n = nums.length;
        boolean[] isPrime = new boolean[MAX_PRIME];
        Arrays.fill(isPrime, true);
        for (int i = 2; i < MAX_PRIME; i++) {
            if (!isPrime[i]) continue;
            for (int j = i * i; j < MAX_PRIME; j += i) {
                isPrime[j] = false;
            }
        }

        int[] primes = new int[10];
        int primeCount = 0;
        for (int i = 2; i < MAX_PRIME; i++) {
            if (isPrime[i]) primes[primeCount++] = i;
        }

        long[][] dp = new long[n][1 << primeCount];
        for (long[] row : dp) Arrays.fill(row, -1);

        int countOnes = 0;
        for (int num : nums) {
            if (num == 1) countOnes++;
        }
        return (int) ((countOnes * dfs(nums, primes, 0, 0, dp)) % MOD);
    }

    private long dfs(int[] nums, int[] primes, int index, int mask, long[][] dp) {
        if (index == nums.length) return mask > 0 ? 1 : 0;
        if (dp[index][mask] != -1) return dp[index][mask];

        long result = dfs(nums, primes, index + 1, mask, dp);
        int num = nums[index];
        boolean isOne = num == 1;

        for (int i = 0; i < primes.length; i++) {
            if (num % (primes[i] * primes[i]) != 0) continue;
            int newMask = mask | (1 << i);
            if ((newMask & (newMask - 1)) == 0 || isOne) {
                result += dfs(nums, primes, index + 1, newMask, dp);
                result %= MOD;
            }
        }

        return dp[index][mask] = result;
    }
}

