// #Hard #Array #Depth_First_Search #Breadth_First_Search #Binary_Search #Matrix #Union_Find
// #2022_05_21_Time_14_ms_(95.24%)_Space_102.7_MB_(69.39%)
public class Solution {
    public int latestDayToCross(int row, int col, int[][] cells) {
        int low = 0;
        int high = cells.length;

        while (low < high) {
            int mid = low + (high - low + 1) / 2;
            if (canReachTop(row, col, cells, mid)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }

        return low;
    }

    private boolean canReachTop(int row, int col, int[][] cells, int day) {
        boolean[][] visited = new boolean[row][col];
        for (int i = 0; i < day; i++) {
            visited[cells[i][0] - 1][cells[i][1] - 1] = true;
        }

        Queue<int[]> queue = new LinkedList<>();
        for (int j = 0; j < col; j++) {
            if (!visited[row - 1][j]) {
                queue.offer(new int[] { row - 1, j });
                visited[row - 1][j] = true;
            }
        }

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            for (int[] dir : new int[][] {{-1, 0}, {1, 0}, {0, -1}, {0, 1}}) {
                int x = current[0] + dir[0];
                int y = current[1] + dir[1];

                if (x < 0 || x >= row || y < 0 || y >= col || visited[x][y]) {
                    continue;
                }

                if (!visited[x][y] && cells[day - 1][0] != x + 1 || cells[day - 1][1] != y + 1) {
                    queue.offer(new int[] {x, y});
                    visited[x][y] = true;

                    if (x == 0) {
                        return true;
                    }
                }
            }
        }

        return false;
    }
}

