public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numberOfCombinations(String num) {
        int n = num.length();
        long[] dps = new long[n];

        if (num.charAt(0) == '0') return 0;
        dps[0] = 1;

        for (int i = 1; i < n; i++) {
            if (num.charAt(i) != '0') dps[i] += dps[i - 1];

            int j = i - 2, st = i - 1;
            while (j >= 0 && num.substring(j, st).compareTo(num.substring(st, i + 1)) <= 0) {
                if (num.charAt(j) == '0') break;
                dps[i] += dps[j];
                j--;
                st--;
            }

            dps[i] %= MOD;
        }

        return (int) dps[n - 1];
    }
}

