// #Hard #Array #String #Hash_Table #Trie #Hash_Function
// #2022_05_18_Time_92_ms_(97.82%)_Space_69.5_MB_(93.45%)
public class Solution {
    public List<List<String>> deleteDuplicateFolder(List<List<String>> paths) {
        Map<String, TrieNode> map = new HashMap<>();
        for (List<String> path : paths) {
            String key = serialize(path);
            if (!map.containsKey(key)) {
                map.put(key, new TrieNode());
            }
            TrieNode root = map.get(key);
            for (String dir : path) {
                if (!root.children.containsKey(dir)) {
                    root.children.put(dir, new TrieNode());
                }
                root = root.children.get(dir);
            }
        }

        Set<TrieNode> set = new HashSet<>();
        dfs(map.values().iterator().next(), set);

        List<List<String>> res = new ArrayList<>();
        for (List<String> path : paths) {
            String key = serialize(path);
            TrieNode node = map.get(key);
            if (!set.contains(node)) {
                res.add(path);
            }
        }

        return res;
    }

    private void dfs(TrieNode root, Set<TrieNode> set) {
        boolean isLeaf = true;
        for (TrieNode child : root.children.values()) {
            dfs(child, set);
            if (!set.contains(child)) {
                isLeaf = false;
            }
        }
        if (isLeaf && root.children.size() > 0) {
            set.add(root);
        }
    }

    private String serialize(List<String> path) {
        StringBuilder sb = new StringBuilder();
        for (String dir : path) {
            sb.append(dir).append(",");
        }
        return sb.toString();
    }

    class TrieNode {
        Map<String, TrieNode> children = new HashMap<>();
    }
}

