public class Solution {
    public long maxProduct(String s) {
        int n = s.length();
        boolean[][] palindrome = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            palindrome[i][i] = true;
        }
        for (int i = 0; i < n - 1; i++) {
            if (s.charAt(i) == s.charAt(i + 1)) {
                palindrome[i][i + 1] = true;
            }
        }
        for (int length = 3; length <= n; length++) {
            for (int start = 0; start < n - length + 1; start++) {
                int end = start + length - 1;
                if (s.charAt(start) == s.charAt(end) && palindrome[start + 1][end - 1]) {
                    palindrome[start][end] = true;
                }
            }
        }

        long[] maxLen = new long[n];
        for (int i = n - 1; i >= 0; i--) {
            if (palindrome[i][i]) {
                maxLen[i] = 1;
            } else {
                maxLen[i] = 0;
            }
            for (int j = i + 2; j < n; j += 2) {
                if (palindrome[i][j]) {
                    maxLen[i] = Math.max(maxLen[i], j - i + 1);
                }
            }
        }

        long res = 0;
        for (int i = 0; i < n - 1; i++) {
            for (int j = i + 2; j < n; j += 2) {
                if (palindrome[i][j] && maxLen[j + 1] > 0) {
                    res = Math.max(res, (long)(j - i + 1) * maxLen[j + 1]);
                }
            }
        }

        return res;
    }
}

