import java.util.*;

public class Solution {
    public int minCost(int maxTime, int[][] edges, int[] passingFees) {
        int n = passingFees.length;
        List<int[]>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            graph[edge[0]].add(new int[]{edge[1], edge[2]});
            graph[edge[1]].add(new int[]{edge[0], edge[2]});
        }

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[1] - b[1]);
        boolean[] visited = new boolean[n];
        long[][] dp = new long[n][maxTime + 1];

        for (int i = 0; i < n; i++) {
            Arrays.fill(dp[i], Long.MAX_VALUE);
        }

        pq.offer(new int[]{0, passingFees[0]});
        dp[0][0] = passingFees[0];

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            if (visited[curr[0]]) continue;
            visited[curr[0]] = true;

            for (int[] next : graph[curr[0]]) {
                long time = curr[1] + next[1];
                if (time <= maxTime) {
                    long cost = dp[curr[0]][curr[1]] + passingFees[next[0]];
                    if (cost < dp[next[0]][(int) time]) {
                        dp[next[0]][(int) time] = cost;
                        pq.offer(new int[]{next[0], (int) time});
                    }
                }
            }
        }

        long res = Long.MAX_VALUE;
        for (long[] arr : dp[n - 1]) {
            if (arr < res) res = arr;
        }

        return res == Long.MAX_VALUE ? -1 : (int) res;
    }
}

