public class Solution {
    public boolean sumGame(String num) {
        int n = num.length();
        long leftSum = 0, rightSum = 0;

        for (int i = 0; i < n / 2; i++) {
            if (num.charAt(i) == '?') {
                leftSum += 9;
            } else {
                leftSum += num.charAt(i) - '0';
            }
        }

        for (int i = n / 2; i < n; i++) {
            if (num.charAt(i) == '?') {
                rightSum += 9;
            } else {
                rightSum += num.charAt(i) - '0';
            }
        }

        return leftSum != rightSum;
    }
}

