        int q = queries.length;
        for (int i = 0; i < q; i++) {
            queryMap.computeIfAbsent(queries[i][0], k -> new ArrayList<>()).add(new int[]{i, queries[i][1]});
        }

        Trie trie = new Trie();
        int[] res = new int[q];

        dfs(graph, queryMap, trie, 0, res);

        return res;
    }

    private void dfs(List<Integer>[] graph, Map<Integer, List<int[]>> queryMap, Trie trie, int node, int[] res) {
        if (queryMap.containsKey(node)) {
            for (int[] query : queryMap.get(node)) {
                res[query[0]] = trie.getMaxXor(query[1]);
            }
        }

        trie.add(node);

        for (int child : graph[node]) {
            dfs(graph, queryMap, trie, child, res);
        }

        trie.remove(node);
    }

    static class Trie {
        private final int L = 30;
        private final int[][] children = new int[1 << L][2];
        private int idx = 0;

        public void add(int x) {
            int node = 0;
            for (int i = L - 1; i >= 0; --i) {
                boolean bit = ((x >> i) & 1) == 1;
                if (children[node][bit ^ 1] != 0) {
                    node = children[node][bit ^ 1];
                } else {
                    children[node][bit ^ 1] = ++idx;
                    node = idx;
                }
            }
        }

        public int getMaxXor(int x) {
            int res = 0, node = 0;
            for (int i = L - 1; i >= 0; --i) {
                boolean bit = ((x >> i) & 1) == 1;
                if (children[node][bit] != 0) {
                    res |= 1 << i;
                    node = children[node][bit];
                } else {
                    node = children[node][bit ^ 1];
                }
            }
            return res;
        }

        public void remove(int x) {
            remove(x, L - 1, 0);
        }

        private boolean remove(int x, int i, int node) {
            if (i < 0) return true;

            boolean bit = ((x >> i) & 1) == 1;
            if (!remove(x, i - 1, children[node][bit])) return false;

            children[node][bit] = 0;
            return children[node][bit ^ 1] == 0;
        }
    }
}

