import java.util.HashSet;
import java.util.Random;

// #Hard #Array #Binary_Search #Hash_Function #Rolling_Hash #Suffix_Array
// #2022_05_15_Time_517_ms_(73.88%)_Space_209.3_MB_(50.00%)
public class Solution {
    private static final int MOD = 1000000007;
    private static final Random RAND = new Random();

    public int longestCommonSubpath(int n, int[][] paths) {
        int low = 0, high = Math.min(getMaxLength(paths), n);
        while (low < high) {
            int mid = low + (high - low + 1) / 2;
            if (!isValid(mid, paths)) {
                high = mid - 1;
            } else {
                low = mid;
            }
        }
        return low;
    }

    private boolean isValid(int length, int[][] paths) {
        HashSet<Long> set = new HashSet<>();
        for (int[] path : paths) {
            long hash = getHash(path, length);
            if (!set.isEmpty() && !set.contains(hash)) {
                return false;
            }
            set.add(hash);
        }
        return true;
    }

    private int getMaxLength(int[][] paths) {
        int maxLen = 0;
        for (int[] path : paths) {
            maxLen = Math.max(maxLen, path.length);
        }
        return maxLen;
    }

    private long getHash(int[] path, int length) {
        long hash = 0;
        long base = RAND.nextLong();
        for (int i = 0; i < length; i++) {
            hash = (hash * base + path[i]) % MOD;
        }
        return hash;
    }

    private boolean equal(int[] a, int startA, int[] b, int startB, int len) {
        for (int i = 0; i < len; i++) {
            if (a[startA + i] != b[startB + i]) {
                return false;
            }
        }
        return true;
    }

    private boolean check(int[][] paths, int len) {
        outer:
        for (int start = 0; start <= paths[0].length - len; start++) {
            for (int[] path : paths) {
                if (path.length < len) {
                    continue outer;
                }
                boolean found = false;
                for (int j = 0; j <= path.length - len; j++) {
                    if (equal(paths[0], start, path, j, len)) {
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    continue outer;
                }
            }
            return true;
        }
        return false;
    }
}

