import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public int nearestExit(char[][] maze, int[] entrance) {
        int m = maze.length, n = maze[0].length;
        boolean[][] visited = new boolean[m][n];
        Queue<int[]> queue = new LinkedList<>();

        // mark the entrance as visited and add it to the queue
        visited[entrance[0]][entrance[1]] = true;
        queue.offer(new int[] {entrance[0], entrance[1], 0});

        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int x = current[0], y = current[1], steps = current[2];

            // if this is an exit cell and not the entrance, return the number of steps
            if ((x == 0 || x == m - 1 || y == 0 || y == n - 1) && (x != entrance[0] || y != entrance[1])) {
                return steps;
            }

            // explore all neighboring cells
            for (int[] direction : directions) {
                int newX = x + direction[0], newY = y + direction[1];

                // if the new cell is within bounds, not a wall and not visited before
                if (newX >= 0 && newX < m && newY >= 0 && newY < n && maze[newX][newY] == '.' && !visited[newX][newY]) {
                    queue.offer(new int[] {newX, newY, steps + 1});
                    visited[newX][newY] = true;
                }
            }
        }

        // if no exit is found
        return -1;
    }
}

