public class Solution {
    public int removeBoxes(int[] boxes) {
        return dfs(boxes, 0, boxes.length - 1, new Integer[boxes.length][boxes.length]);
    }

    private int dfs(int[] boxes, int l, int r, Integer[][] memo) {
        if (l > r) return 0;
        if (memo[l][r] != null) return memo[l][r];
        while (l + 1 <= r && boxes[l] == boxes[l + 1]) ++l;
        int res = (r - l + 1) * (r - l + 1) + dfs(boxes, l + 1, r, memo);
        for (int i = l + 1; i <= r; ++i)
            if (boxes[l] == boxes[i])
                res = Math.max(res, dfs(boxes, l + 1, i - 1, memo) + dfs(boxes, i, r, memo));
        return memo[l][r] = res;
    }
}

