public class Solution {
    public boolean isValid(String code) {
        Deque<String> stack = new ArrayDeque<>();

        for (int i = 0; i < code.length(); ) {
            if (code.startsWith("<![CDATA[", i)) {
                int j = code.indexOf("]]>", i);
                if (j == -1) return false;
                i = j + 3;
            } else if (code.startsWith("</", i)) {
                int j = code.indexOf('>', i);
                if (j == -1 || !isValidTagName(code.substring(i + 2, j))) return false;
                String tagName = code.substring(i + 2, j);
                if (stack.isEmpty() || stack.pop().equals(tagName)) return false;
                i = j + 1;
            } else if (code.startsWith("<", i)) {
                int j = code.indexOf('>', i);
                if (j == -1) return false;
                String tagName = code.substring(i + 1, j);
                if (!isValidTagName(tagName)) return false;
                stack.push(tagName);
                i = j + 1;
            } else {
                i++;
            }
        }

        return stack.isEmpty();
    }

    private boolean isValidTagName(String tagName) {
        for (char c : tagName.toCharArray()) {
            if (!Character.isUpperCase(c)) return false;
        }
        return tagName.length() >= 1 && tagName.length() <= 9;
    }
}

