// #Medium #Top_100_Liked_Questions #String #Hash_Table #Two_Pointers #Sliding_Window
// #Algorithm_I_Day_6_Sliding_Window #2022_08_10_Time_5_ms_(93.93%)_Space_43.1_MB_(71.37%)
public class Solution {
    public boolean checkInclusion(String s1, String s2) {
        if (s1.length() > s2.length()) return false;

        Map<Character, Integer> count = new HashMap<>();
        for (char c : s1.toCharArray()) {
            count.put(c, count.getOrDefault(c, 0) + 1);
        }

        int requiredChars = count.size();
        int formedChars = 0;

        Map<Character, Integer> windowCounts = new HashMap<>();
        int left = 0;

        for (int right = 0; right < s2.length(); right++) {
            char c = s2.charAt(right);

            if (count.containsKey(c)) {
                windowCounts.put(c, windowCounts.getOrDefault(c, 0) + 1);

                if (windowCounts.get(c).equals(count.get(c))) {
                    formedChars++;
                }
            }

            while (right - left + 1 >= s1.length()) {
                if (formedChars == requiredChars) return true;

                char ch = s2.charAt(left);

                if (count.containsKey(ch)) {
                    windowCounts.put(ch, windowCounts.get(ch) - 1);

                    if (!windowCounts.get(ch).equals(count.get(ch))) {
                        formedChars--;
                    }
                }

                left++;
            }
        }

        return false;
    }
}

