public class Solution {
    public int nextGreaterElement(int n) {
        char[] num = String.valueOf(n).toCharArray();
        int k = num.length - 2;

        // Find k
        while (k >= 0 && num[k] >= num[k + 1]) {
            k--;
        }

        if (k < 0) return -1;

        // Find l
        int l = num.length - 1;
        while (num[l] <= num[k]) {
            l--;
        }

        // Swap k and l
        swap(num, k, l);

        // Reverse from k + 1 to end
        reverse(num, k + 1);

        long ret = Long.parseLong(new String(num));

        // Handle the case if ret > Integer.MAX_VALUE
        return (ret > Integer.MAX_VALUE) ? -1 : (int) ret;
    }

    private void swap(char[] num, int i, int j) {
        char temp = num[i];
        num[i] = num[j];
        num[j] = temp;
    }

    private void reverse(char[] num, int start) {
        int left = start;
        int right = num.length - 1;

        while (left < right) {
            swap(num, left++, right--);
        }
    }
}

