import java.util.ArrayList;
import java.util.List;

public class Solution {
    public String fractionAddition(String expression) {
        int A = 0, B = 1; // initialize numerator and denominator
        int n = expression.length();
        int i = 0;

        while (i < n) {
            int sign = 1; // default sign is positive
            if (expression.charAt(i) == '-') {
                sign = -1;
                i++;
            } else if (expression.charAt(i) == '+') {
                i++;
            }

            int numerator = 0, denominator = 0;
            boolean isNumerator = true;
            while (i < n && expression.charAt(i) != '+' && expression.charAt(i) != '-') {
                if (expression.charAt(i) == '/') {
                    isNumerator = false;
                    i++;
                } else {
                    int digit = expression.charAt(i++) - '0';
                    if (isNumerator) {
                        numerator = numerator * 10 + digit;
                    } else {
                        denominator = denominator * 10 + digit;
                    }
                }
            }

            A = A * denominator + sign * numerator * B; // update numerator
            B *= denominator; // update denominator

            int gcd = gcd(A, B); // calculate GCD of A and B
            A /= gcd; // simplify fraction
            B /= gcd;
        }

        return A + "/" + B;
    }

    private int gcd(int a, int b) {
        if (b == 0) {
            return a;
        } else {
            return gcd(b, a % b);
        }
    }
}

