        HashSet<Integer> set = new HashSet<>();
        HashSet<String> pairs = new HashSet<>();

        for (int num : nums) {
            if (!set.add(num)) continue;

            if (set.contains(num - k)) {
                String pair = Math.min(num, num-k) + "," + Math.max(num, num-k);
                pairs.add(pair);
            }

            if (set.contains(num + k)) {
                String pair = Math.min(num, num+k) + "," + Math.max(num, num+k);
                pairs.add(pair);
            }
        }

        return pairs.size();
    }
