// #2022_07_28_Time_0_ms_(100.00%)_Space_42.6_MB_(85.88%)
public class Solution {
    public char[][] updateBoard(char[][] board, int[] click) {
        if (board[click[0]][click[1]] == 'M') {
            board[click[0]][click[1]] = 'X';
            return board;
        }
        reveal(board, click[0], click[1]);
        return board;
    }

    private void reveal(char[][] board, int row, int col) {
        if (row < 0 || row >= board.length || col < 0 || col >= board[0].length
                || board[row][col] != 'E') {
            return;
        }
        int mines = countMines(board, row, col);
        if (mines > 0) {
            board[row][col] = (char) ('0' + mines);
            return;
        } else {
            board[row][col] = 'B';
            reveal(board, row - 1, col); // top
            reveal(board, row + 1, col); // bottom
            reveal(board, row, col - 1); // left
            reveal(board, row, col + 1); // right
            reveal(board, row - 1, col - 1); // top-left
            reveal(board, row - 1, col + 1); // top-right
            reveal(board, row + 1, col - 1); // bottom-left
            reveal(board, row + 1, col + 1); // bottom-right
        }
    }

    private int countMines(char[][] board, int row, int col) {
        int mines = 0;
        for (int i = Math.max(0, row - 1); i <= Math.min(row + 1, board.length - 1); i++) {
            for (int j = Math.max(0, col - 1); j <= Math.min(col + 1, board[0].length - 1); j++) {
                if ((i != row || j != col) && board[i][j] == 'M') {
                    mines++;
                }
            }
        }
        return mines;
    }
}

