import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int findRotateSteps(String ring, String key) {
        List<Integer>[] pos = new List[26];
        for (int i = 0; i < 26; ++i)
            pos[i] = new ArrayList<>();

        for (int i = 0; i < ring.length(); ++i)
            pos[ring.charAt(i) - 'a'].add(i);

        int[][] dp = new int[key.length()][ring.length()];
        for (int[] d : dp)
            java.util.Arrays.fill(d, Integer.MAX_VALUE / 2);

        for (int p : pos[key.charAt(0) - 'a'])
            dp[0][p] = Math.min(p, ring.length() - p) + 1;

        for (int i = 1; i < key.length(); ++i)
            for (int j : pos[key.charAt(i) - 'a']) {
                int min = Integer.MAX_VALUE / 2;
                for (int k : pos[key.charAt(i - 1) - 'a'])
                    min = Math.min(min, dp[i - 1][k]);
                dp[i][j] = Math.min(dp[i][j], min + Math.abs(j - pos[key.charAt(i - 1) - 'a'].get(0)) + 1);

                for (int k : pos[key.charAt(i - 1) - 'a'])
                    if (pos[key.charAt(i - 1) - 'a'].indexOf(k) != pos[key.charAt(i - 1) - 'a'].size() - 1)
                        dp[i][j] = Math.min(dp[i][j], dp[i - 1][k] + ring.length() - Math.abs(j - k) + 1);
            }

        int res = Integer.MAX_VALUE / 2;
        for (int i : pos[key.charAt(key.length() - 1) - 'a'])
            res = Math.min(res, dp[key.length() - 1][i]);

        return res;
    }
}

