public class Solution {
    public String nearestPalindromic(String n) {
        long num = Long.parseLong(n);
        long diff1 = getDiff(num, getPalindrome(num));
        if (diff1 == 0) return n;

        long candidate1 = getPalindrome(num - 1);
        long candidate2 = getPalindrome(num + 1);

        long diff2 = Math.abs(candidate1 - num);
        long diff3 = Math.abs(candidate2 - num);

        if (diff2 <= diff3 && diff2 < diff1) {
            return String.valueOf(candidate1);
        } else if (diff3 < diff2 && diff3 < diff1) {
            return String.valueOf(candidate2);
        }

        return String.valueOf(getPalindrome(num));
    }

    private long getDiff(long num, long palindrome) {
        return Math.abs(num - palindrome);
    }

    private long getPalindrome(long num) {
        if (num < 10) return num;

        int len = String.valueOf(num).length();
        long firstHalf = Long.parseLong(String.valueOf(num).substring(0, (len + 1) / 2));

        if (len % 2 == 0) {
            return Long.parseLong(String.valueOf(firstHalf) + new StringBuilder(String.valueOf(firstHalf)).reverse().toString());
        } else {
            return Long.parseLong(String.valueOf(firstHalf) + String.valueOf(firstHalf).charAt(len / 2 - 1) + new StringBuilder(String.valueOf(firstHalf)).reverse().toString());
        }
    }
}

