public class Solution {
    public int findIntegers(int n) {
        int[] dp = new int[32];
        dp[0] = 1;
        dp[1] = 2;

        for (int i = 2; i < 32; i++) {
            dp[i] = dp[i - 1] + dp[i - 2];
        }

        int result = 0, prevBit = 0;
        for (int i = 30; i >= 0; i--) {
            int currBit = (n >> i) & 1;

            if (currBit == 1) {
                result += dp[i];

                if (prevBit == 1) {
                    result++;
                    break;
                }
            }

            prevBit = currBit;
        }

        return n + 1 - result;
    }
}

