// #2022_07_24_Time_51_ms_(89.62%)_Space_101.7_MB_(47.03%)
import java.util.Comparator;
import java.util.PriorityQueue;

public class Solution {
    public int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
        Project[] projects = new Project[profits.length];
        for (int i = 0; i < profits.length; i++) {
            projects[i] = new Project(profits[i], capital[i]);
        }

        java.util.Arrays.sort(projects, Comparator.comparingInt(p -> p.capital));

        PriorityQueue<Project> maxHeap = new PriorityQueue<>((a, b) -> Integer.compare(b.profit, a.profit));

        int i = 0;
        while (k-- > 0) {
            while (i < projects.length && projects[i].capital <= w) {
                maxHeap.offer(projects[i++]);
            }

            if (maxHeap.isEmpty()) break;

            Project project = maxHeap.poll();
            w += project.profit;
        }

        return w;
    }

    private static class Project {
        int profit, capital;
        public Project(int profit, int capital) {
            this.profit = profit;
            this.capital = capital;
        }
    }
}

