public class Solution {
    public int findUnsortedSubarray(int[] nums) {
        int n = nums.length;
        int[] copy = new int[n];
        System.arraycopy(nums, 0, copy, 0, n);
        java.util.Arrays.sort(copy);

        int start = n, end = 0;

        for (int i = 0; i < n; i++) {
            if (nums[i] != copy[i]) {
                start = Math.min(start, i);
                end = Math.max(end, i);
            }
        }

        return end - start >= 0 ? end - start + 1 : 0;
    }
}

