// #Easy #Depth_First_Search #Tree #Binary_Tree
// #2022_08_03_Time_1_ms_(81.35%)_Space_45.4_MB_(40.75%)
import com_github_leetcode.TreeNode;

public class Solution {
    private int tiltSum = 0;

    public int findTilt(TreeNode root) {
        traverse(root);
        return tiltSum;
    }

    private int traverse(TreeNode node) {
        if (node == null) {
            return 0;
        }

        int leftSum = traverse(node.left);
        int rightSum = traverse(node.right);

        tiltSum += Math.abs(leftSum - rightSum);

        return node.val + leftSum + rightSum;
    }
}

