public class Solution {
    public boolean validSquare(int[] p1, int[] p2, int[] p3, int[] p4) {
        int[][] points = {p1, p2, p3, p4};
        Arrays.sort(points, (a, b) -> a[0] == b[0] ? Integer.compare(a[1], b[1]) : Integer.compare(a[0], b[0]));

        return dist(points[0], points[1]) != 0 
            && dist(points[0], points[1]) == dist(points[1], points[2])
            && dist(points[1], points[2]) == dist(points[2], points[3])
            && dist(points[2], points[3]) == dist(points[3], points[0])
            && dist(points[0], points[2]) == dist(points[1], points[3]);
    }

    private int dist(int[] p1, int[] p2) {
        return (p1[0] - p2[0]) * (p1[0] - p2[0]) + (p1[1] - p2[1]) * (p1[1] - p2[1]);
    }
}

