// #Medium #Dynamic_Programming #2022_08_10_Time_5_ms_(92.95%)_Space_43.1_MB_(36.44%)
import java.util.Arrays;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int findPaths(int m, int n, int maxMove, int startRow, int startColumn) {
        int[][][] dp = new int[maxMove + 1][m][n];

        for (int k = 1; k <= maxMove; k++) {
            for (int i = 0; i < m; i++) {
                for (int j = 0; j < n; j++) {
                    if (i == 0) dp[k][i][j] += 1;
                    if (j == 0) dp[k][i][j] += 1;
                    if (i == m - 1) dp[k][i][j] += 1;
                    if (j == n - 1) dp[k][i][j] += 1;

                    if (k > 1) {
                        if (i > 0) dp[k][i][j] = (dp[k][i][j] + dp[k - 1][i - 1][j]) % MOD;
                        if (i < m - 1) dp[k][i][j] = (dp[k][i][j] + dp[k - 1][i + 1][j]) % MOD;
                        if (j > 0) dp[k][i][j] = (dp[k][i][j] + dp[k - 1][i][j - 1]) % MOD;
                        if (j < n - 1) dp[k][i][j] = (dp[k][i][j] + dp[k - 1][i][j + 1]) % MOD;
                    }
                }
            }
        }

        int res = 0;
        for (int k = 1; k <= maxMove; k++) {
            res = (res + dp[k][startRow][startColumn]) % MOD;
        }

        return res;
    }
}

