import java.util.Arrays;
import java.util.Comparator;

// #Hard #Array #Math #Geometry #2022_08_25_Time_12_ms_(90.91%)_Space_54.5_MB_(58.18%)
public class Solution {
    public int[][] outerTrees(int[][] trees) {
        if (trees.length <= 3) return trees;

        Arrays.sort(trees, Comparator.comparingInt(o -> o[0]));

        int n = trees.length;
        int[] hull = new int[n * 2];
        int k = 0;

        for (int i = 0; i < n; i++) {
            while (k > 1 && cross(hull[k - 2], hull[k - 1], trees[i]) < 0) k--;
            hull[k++] = i;
        }

        for (int i = n - 2, t = k + 1; i >= 0; i--) {
            while (k > t && cross(hull[k - 2], hull[k - 1], trees[i]) < 0) k--;
            hull[k++] = i;
        }

        int[][] result = new int[k - 1][2];
        for (int i = 0; i < k - 1; i++) {
            result[i] = trees[hull[i]];
        }

        return result;
    }

    private int cross(int[] p, int[] q, int[] r) {
        return (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0]);
    }
}

