// #Hard #Dynamic_Programming #2022_08_03_Time_11_ms_(98.55%)_Space_41.6_MB_(87.84%)
import java.util.Arrays;
public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int checkRecord(int n) {
        long[] dp = new long[3];
        Arrays.fill(dp, 1);

        for (int i = 2; i < n; ++i) {
            long[] nextDp = new long[3];

            // P
            nextDp[0] = (dp[0] + dp[1] + dp[2]) % MOD;

            // L
            nextDp[1] = dp[0];
            nextDp[2] = dp[1];

            dp = nextDp;
        }

        long res = (dp[0] + dp[1] + dp[2]) % MOD;

        for (int i = 1; i < n; ++i) {
            res = (res + ((long) pow(3, i - 1) * (n - i))) % MOD;
        }

        return (int) res;
    }

    private long pow(long a, int b) {
        if (b == 0) return 1;
        long half = pow(a, b / 2);
        if ((b & 1) == 0) return (half * half) % MOD;
        else return (((half * half) % MOD) * a) % MOD;
    }
}

