public class Solution {
    public int numSubmat(int[][] mat) {
        int m = mat.length, n = mat[0].length;
        int[] height = new int[n];
        int res = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i > 0) {
                    height[j] = mat[i][j] == 1 ? height[j] + 1 : 0;
                } else {
                    height[j] = mat[i][j];
                }
            }

            int[] stack = new int[n + 1];
            int top = -1;
            for (int j = 0; j < n; j++) {
                while (top >= 0 && height[stack[top]] > height[j]) {
                    int h = height[stack[top--]];
                    int w = top >= 0 ? j - stack[top] : j + 1;
                    res += h * w;
                }
                stack[++top] = j;
            }

            while (top >= 0) {
                int h = height[stack[top--]];
                int w = top >= 0 ? n - stack[top] : n;
                res += h * w;
            }
        }

        return res;
    }
}

