import java.util.Arrays;
import java.util.Random;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;
    private Random random = new Random();

    public int numOfWays(int[] nums) {
        return dfs(nums) - 1;
    }

    private long dfs(int[] nums) {
        if (nums.length <= 2) {
            return 1;
        }
        int root = nums[random.nextInt(nums.length)];
        int[] left = Arrays.stream(nums).filter(x -> x < root).toArray();
        int[] right = Arrays.stream(nums).filter(x -> x > root).toArray();

        long res = dfs(left) * dfs(right);
        res %= MOD;

        // calculate the number of ways to reorder left and right subtrees
        long ways = nPermuteM(left.length + right.length, left.length);
        ways %= MOD;
        return res * ways % MOD;
    }

    private long nPermuteM(int n, int m) {
        long res = 1;
        for (int i = n; i > n - m; --i) {
            res *= i;
            res %= MOD;
        }
        return res;
    }
}

