// #Hard #String #Sorting #Greedy #2022_04_11_Time_20_ms_(97.22%)_Space_54.4_MB_(72.22%)
public class Solution {
    public boolean isTransformable(String s, String t) {
        if (s.length() != t.length()) return false;

        Map<Character, Deque<Integer>> index = new HashMap<>();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            index.computeIfAbsent(c, k -> new ArrayDeque<>()).addLast(i);
        }

        int[] pos = new int[10];
        for (char c : t.toCharArray()) {
            int d = c - '0';
            if (pos[d] == 0) continue;

            for (int i = 0; i < d; i++) {
                if (!index.containsKey((char)(i + '0'))) break;

                while (!index.get((char)(i + '0')).isEmpty() && index.get((char)(i + '0')).peekFirst() < pos[d]) 
                    index.get((char)(i + '0')).pollFirst();

                if (index.get((char)(i + '0')).isEmpty()) return false;
            }

            pos[d] = index.get((char)(d + '0')).pollFirst() + 1;
        }

        return true;
    }
}

