import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int unhappyFriends(int n, int[][] preferences, int[][] pairs) {
        Map<Integer, Integer> pairMap = new HashMap<>();

        // Create a map to store each person's pair
        for (int[] pair : pairs) {
            pairMap.put(pair[0], pair[1]);
            pairMap.put(pair[1], pair[0]);
        }

        int unhappyCount = 0;

        // Iterate over each person and their preferences
        for (int i = 0; i < n; i++) {
            int[] preference = preferences[i];
            int pair = pairMap.get(i);

            // Check if the person is unhappy with their current pair
            for (int j : preference) {
                if (j == pair) break;

                // If a more preferred friend exists and they also prefer this person over their own pair, increment unhappy count
                int[] otherPreference = preferences[j];
                int otherPair = pairMap.get(j);
                boolean isUnhappy = false;
                for (int k : otherPreference) {
                    if (k == i) {
                        isUnhappy = true;
                        break;
                    }
                    if (k == otherPair) break;
                }

                if (isUnhappy) {
                    unhappyCount++;
                    break;
                }
            }
        }

        return unhappyCount;
    }
}

