public class Solution {
    public int minInsertions(String s) {
        int res = 0, stack = 0;
        for (int i = 0; i < s.length(); ++i) {
            if (s.charAt(i) == '(') {
                if ((stack & 1) > 0) {
                    res++;
                }
                stack += 2;
            } else {
                if ((stack & 1) == 0) {
                    if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                        i++;
                    } else {
                        res++;
                    }
                }
                stack--;
                if (stack < 0) {
                    stack = 0;
                }
            }
        }
        return res + stack / 2 * 2;
    }
}

