import java.util.Arrays;
// #Medium #Array #Sorting #Binary_Search #Binary_Search_II_Day_4
// #2022_04_11_Time_39_ms_(99.65%)_Space_56.9_MB_(90.25%)
public class Solution {
    public int maxDistance(int[] position, int m) {
        Arrays.sort(position);
        int left = 1;
        int right = (position[position.length - 1] - position[0]) / (m - 1) + 1;

        while (left < right) {
            int mid = left + (right - left) / 2;
            if (!possible(position, m, mid)) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        return left;
    }

    private boolean possible(int[] position, int m, int minDistance) {
        int count = 1;
        int prev = position[0];

        for (int i = 1; i < position.length; i++) {
            if (position[i] - prev >= minDistance) {
                count++;
                prev = position[i];
            }
        }

        return count >= m;
    }
}

