public class Solution {
    public int minOperationsMaxProfit(int[] customers, int boardingCost, int runningCost) {
        int maxProfit = 0;
        int maxRotations = -1;
        int waitingCustomers = 0;
        int rotations = 0;
        int currentProfit = 0;

        for (int i = 0; i < customers.length || waitingCustomers > 0; i++) {
            if (i < customers.length) {
                waitingCustomers += customers[i];
            }

            int boarding = Math.min(4, waitingCustomers);
            waitingCustomers -= boarding;
            rotations++;
            currentProfit += boarding * boardingCost - runningCost;

            if (currentProfit > maxProfit) {
                maxProfit = currentProfit;
                maxRotations = rotations;
            }
        }

        return maxRotations;
    }
}

