import java.util.Arrays;
import java.util.List;

public class Solution {
    public int connectTwoGroups(List<List<Integer>> cost) {
        int m = cost.size();
        int n = cost.get(0).size();
        int[] record = new int[1 << n];
        Arrays.fill(record, Integer.MAX_VALUE);
        record[0] = 0;

        for (int i = 0; i < m; i++) {
            int[] tmpRecord = new int[record.length];
            Arrays.fill(tmpRecord, Integer.MAX_VALUE);

            for (int j = 0; j < (1 << n); j++) {
                if (record[j] == Integer.MAX_VALUE) continue;

                for (int k = 0; k < n; k++) {
                    int newMask = j | (1 << k);
                    tmpRecord[newMask] = Math.min(tmpRecord[newMask], record[j] + cost.get(i).get(k));
                }
            }

            for (int j = 0; j < (1 << n); j++) {
                if (Integer.bitCount(j) == n) continue;

                int complement = ((1 << n) - 1) ^ j;
                tmpRecord[complement] = Math.min(tmpRecord[complement], record[j]);
            }

            record = tmpRecord;
        }

        return record[(1 << n) - 1];
    }
}

