public class Solution {
    public int closestToTarget(int[] arr, int target) {
        Set<Integer> set = new HashSet<>();
        set.add(0);
        int res = Integer.MAX_VALUE;

        for (int a : arr) {
            Set<Integer> next = new HashSet<>();
            for (int s : set) {
                int t = s | a;
                res = Math.min(res, Math.abs(t - target));
                next.add(t);
            }
            set = next;
        }

        return res;
    }
}

