public class Solution {
    public boolean containsPattern(int[] arr, int m, int k) {
        for (int i = 0; i <= arr.length - m * k; i++) {
            if (check(arr, i, m, k)) return true;
        }
        return false;
    }

    private boolean check(int[] arr, int start, int m, int k) {
        for (int j = 1; j < k; j++) {
            for (int p = 0; p < m; p++) {
                if (arr[start + (j - 1) * m + p] != arr[start + j * m + p]) return false;
            }
        }
        return true;
    }
}

