            double[] gradientY = new double[positions.length];
            for (int i = 0; i < positions.length; ++i) {
                double dx = center[0] - positions[i][0];
                double dy = center[1] - positions[i][1];
                double dist = Math.sqrt(dx * dx + dy * dy);
                if (dist > EPS) {
                    gradientX[i] = dx / dist;
                    gradientY[i] = dy / dist;
                } else {
                    gradientX[i] = 0;
                    gradientY[i] = 0;
                }
            }

            double[] newCenter = {center[0], center[1]};
            for (int i = 0; i < positions.length; ++i) {
                newCenter[0] -= 4 * EPS * gradientX[i];
                newCenter[1] -= 4 * EPS * gradientY[i];
            }

            if (Math.abs(newCenter[0] - center[0]) < EPS && Math.abs(newCenter[1] - center[1]) < EPS) {
                break;
            }
            center = newCenter;
        }

        double minDistSum = 0;
        for (int[] position : positions) {
            double dx = center[0] - position[0];
            double dy = center[1] - position[1];
            minDistSum += Math.sqrt(dx * dx + dy * dy);
        }
        return minDistSum;
    }
}

