public class Solution {
    public int minSwaps(int[][] grid) {
        int n = grid.length;
        int[] countZeroes = new int[n];

        // Count trailing zeroes in each row
        for (int i = 0; i < n; i++) {
            int j = n - 1;
            while (j >= 0 && grid[i][j] == 0) {
                j--;
            }
            countZeroes[i] = n - j - 1;
        }

        // Greedily try to find a row with enough trailing zeroes
        int swaps = 0;
        for (int i = 0; i < n; i++) {
            boolean found = false;
            for (int j = i; j < n; j++) {
                if (countZeroes[j] >= n - i) {
                    // Swap rows if necessary
                    if (i != j) {
                        int temp = countZeroes[i];
                        countZeroes[i] = countZeroes[j];
                        countZeroes[j] = temp;
                        swaps++;
                    }
                    found = true;
                    break;
                }
            }
            if (!found) return -1; // cannot make the grid valid
        }

        return swaps;
    }
}

