public class Solution {
    public String reorderSpaces(String text) {
        int spaceCount = 0;
        for (char c : text.toCharArray()) {
            if (c == ' ') {
                spaceCount++;
            }
        }

        String[] words = text.trim().split("\\s+");
        StringBuilder sb = new StringBuilder();
        if (words.length > 1) {
            int gapSpaceCount = spaceCount / (words.length - 1);
            int extraSpaceCount = spaceCount % (words.length - 1);

            for (int i = 0; i < words.length; i++) {
                sb.append(words[i]);
                if (i < words.length - 1) {
                    for (int j = 0; j < gapSpaceCount; j++) {
                        sb.append(' ');
                    }
                }
            }

            for (int i = 0; i < extraSpaceCount; i++) {
                sb.append(' ');
            }
        } else {
            sb.append(words[0]);
            for (int i = 0; i < spaceCount; i++) {
                sb.append(' ');
            }
        }

        return sb.toString();
    }
}

