// #2022_04_09_Time_3_ms_(94.18%)_Space_52.2_MB_(60.26%)
import com_github_leetcode.TreeNode;

public class Solution {
    public int countPairs(TreeNode root, int distance) {
        return dfs(root, distance);
    }

    private int[] dfs(TreeNode node, int distance) {
        if (node == null || distance < 0) {
            return new int[1];
        }

        if (node.left == null && node.right == null) {
            return new int[]{1};
        }

        int[] left = dfs(node.left, distance - 1);
        int[] right = dfs(node.right, distance - 1);

        int count = 0;
        for (int i : left) {
            for (int j : right) {
                if (i + j <= distance) {
                    count++;
                }
            }
        }

        int[] res = new int[Math.max(left.length, right.length)];
        System.arraycopy(left, 0, res, 0, left.length);
        System.arraycopy(right, 0, res, left.length, right.length);

        return res;
    }
}

