public class Solution {
    public boolean winnerSquareGame(int n) {
        boolean[] dp = new boolean[n + 1];
        for (int i = 0; i <= n; i++) {
            if (i == 0) {
                dp[i] = false;
            } else {
                dp[i] = !dp[i - 1];
                int j = 2;
                while (j * j <= i) {
                    if (!dp[i - j * j]) {
                        dp[i] = true;
                        break;
                    }
                    j++;
                }
            }
        }
        return dp[n];
    }
