public class Solution {
    public String minInteger(String num, int k) {
        char[] chars = num.toCharArray();
        Deque<Integer>[] deques = new LinkedList[10];
        for (int i = 0; i < 10; i++) {
            deques[i] = new LinkedList<>();
        }

        for (int i = 0; i < chars.length; i++) {
            int digit = chars[i] - '0';
            deques[digit].addLast(i);
        }

        char[] res = new char[chars.length];
        boolean[] visited = new boolean[chars.length];

        for (int i = 0; i < chars.length; i++) {
            for (int j = 0; j <= 9; j++) {
                if (!deques[j].isEmpty() && deques[j].peekFirst() - k + i >= 0) {
                    int index = deques[j].pollFirst();
                    res[i] = (char)(j + '0');
                    visited[index] = true;
                    break;
                }
            }
        }

        for (int i = 0; i < chars.length; i++) {
            if (!visited[i]) {
                for (int j = 0; j <= 9; j++) {
                    if (!deques[j].isEmpty()) {
                        int index = deques[j].pollFirst();
                        res[i] = (char)(j + '0');
                        break;
                    }
                }
            }
        }

        return new String(res);
    }
}

