import java.util.ArrayList;
import java.util.List;

public class Solution {
    private int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    public int minDays(int[][] grid) {
        if (grid == null || grid.length == 0) return 0;

        int m = grid.length;
        int n = grid[0].length;
        boolean hasTwoIslands = false;
        int islandCount = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    dfs(grid, i, j);
                    islandCount++;

                    // If we have more than one island, return 0
                    if (islandCount > 1) return 0;
                }
            }
        }

        // Try to remove each land cell and see if it disconnects the grid
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    grid[i][j] = 0;

                    // Check if removing this cell disconnects the grid
                    int newIslandCount = countIslands(grid);

                    // If it does, return 1
                    if (newIslandCount > 1 || newIslandCount == 0) return 1;

                    // Otherwise, put the cell back and try the next one
                    grid[i][j] = 1;
                }
            }
        }

        // If we can't disconnect the grid by removing a single land cell, return 2
        return 2;
    }

    private void dfs(int[][] grid, int i, int j) {
        if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || grid[i][j] != 1) return;

        grid[i][j] = -1; // Mark as visited

        for (int[] direction : directions) {
            dfs(grid, i + direction[0], j + direction[1]);
        }
    }

    private int countIslands(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int islandCount = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    dfs(grid, i, j);
                    islandCount++;
                }
            }
        }

        return islandCount;
    }
}

