// #Medium #Heap_Priority_Queue #Graph #Shortest_Path
// #2022_04_09_Time_31_ms_(93.10%)_Space_51.7_MB_(98.80%)
public class Solution {
    public double maxProbability(int n, int[][] edges, double[] succProb, int start, int end) {
        List<List<Pair>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        for (int i = 0; i < edges.length; i++) {
            int u = edges[i][0];
            int v = edges[i][1];
            double p = succProb[i];
            graph.get(u).add(new Pair(v, p));
            graph.get(v).add(new Pair(u, p)); // since it's an undirected graph
        }

        PriorityQueue<Pair> pq = new PriorityQueue<>((a, b) -> Double.compare(b.prob, a.prob));
        double[] prob = new double[n];
        Arrays.fill(prob, 0);
        prob[start] = 1;
        pq.offer(new Pair(start, 1));

        while (!pq.isEmpty()) {
            Pair cur = pq.poll();
            int u = cur.node;
            if (u == end) return cur.prob; // found the destination
            for (Pair neighbor : graph.get(u)) {
                int v = neighbor.node;
                double p = neighbor.prob;
                if (cur.prob * p > prob[v]) { // update probability only when it's larger
                    prob[v] = cur.prob * p;
                    pq.offer(new Pair(v, prob[v]));
                }
            }
        }

        return 0; // no path from start to end
    }

    class Pair {
        int node;
        double prob;
        public Pair(int node, double prob) {
            this.node = node;
            this.prob = prob;
        }
    }
}

