public class Solution {
    public boolean isPrintable(int[][] targetGrid) {
        int m = targetGrid.length, n = targetGrid[0].length;
        int[] colorBound = new int[61 * 4];

        for (int i = 0; i < 61 * 4; i++) {
            colorBound[i] = -1;
        }

        // find the color range for each color
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int color = targetGrid[i][j];
                if (colorBound[color * 4] == -1) {
                    colorBound[color * 4] = i;
                    colorBound[color * 4 + 1] = j;
                    colorBound[color * 4 + 2] = i;
                    colorBound[color * 4 + 3] = j;
                } else {
                    colorBound[color * 4] = Math.min(colorBound[color * 4], i);
                    colorBound[color * 4 + 1] = Math.min(colorBound[color * 4 + 1], j);
                    colorBound[color * 4 + 2] = Math.max(colorBound[color * 4 + 2], i);
                    colorBound[color * 4 + 3] = Math.max(colorBound[color * 4 + 3], j);
                }
            }
        }

        boolean[] printed = new boolean[61];

        for (int color = 1; color <= 60; color++) {
            if (!dfs(targetGrid, colorBound, printed, color)) {
                return false;
            }
        }

        return true;
    }

    private boolean dfs(int[][] targetGrid, int[] colorBound, boolean[] printed, int color) {
        if (printed[color]) {
            return true;
        }

        int min_i = colorBound[color * 4];
        int min_j = colorBound[color * 4 + 1];
        int max_i = colorBound[color * 4 + 2];
        int max_j = colorBound[color * 4 + 3];

        for (int i = min_i; i <= max_i; i++) {
            for (int j = min_j; j <= max_j; j++) {
                if (targetGrid[i][j] != color && targetGrid[i][j] != 0) {
                    if (!dfs(targetGrid, colorBound, printed, targetGrid[i][j])) {
                        return false;
                    }
                }
            }
        }

        printed[color] = true;

        for (int i = min_i; i <= max_i; i++) {
            for (int j = min_j; j <= max_j; j++) {
                if (targetGrid[i][j] == color) {
                    targetGrid[i][j] = 0;
                }
            }
        }

        return true;
    }
}

