    private Map<Character, Integer> dfs(List<Integer>[] graph, int node, int parent, char[] labels, int[] result) {
        Map<Character, Integer> countMap = new HashMap<>();
        for (int child : graph[node]) {
            if (child != parent) {
                Map<Character, Integer> childCountMap = dfs(graph, child, node, labels, result);
                for (char c : childCountMap.keySet()) {
                    countMap.put(c, countMap.getOrDefault(c, 0) + childCountMap.get(c));
                }
            }
        }

        char label = labels[node];
        countMap.put(label, countMap.getOrDefault(label, 0) + 1);
        result[node] = countMap.get(label);

        return countMap;
    }
}

