import java.util.*;

public class Solution {
    public List<String> maxNumOfSubstrings(String s) {
        int n = s.length();
        Map<Character, Integer> firstOccurrence = new HashMap<>();
        Map<Character, Integer> lastOccurrence = new HashMap<>();

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (!firstOccurrence.containsKey(c)) {
                firstOccurrence.put(c, i);
            }
            lastOccurrence.put(c, i);
        }

        List<String> result = new ArrayList<>();
        int start = -1;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (firstOccurrence.get(c) == i) {
                start = i;
                int end = lastOccurrence.get(c);
                while (true) {
                    boolean updated = false;
                    for (char cc : firstOccurrence.keySet()) {
                        if (firstOccurrence.get(cc) >= start && firstOccurrence.get(cc) < end
                                && lastOccurrence.get(cc) > end) {
                            end = lastOccurrence.get(cc);
                            updated = true;
                        }
                    }
                    if (!updated) break;
                }
                result.add(s.substring(start, end + 1));
            }
        }

        return result;
    }
}

