        upMin[0][0] = leftMin[0][0] = grid[0][0];

        for (int i = 1; i < m; i++) {
            upMax[i][0] = upMax[i - 1][0] * grid[i][0];
            upMin[i][0] = upMin[i - 1][0] * grid[i][0];
        }

        for (int j = 1; j < n; j++) {
            leftMax[0][j] = leftMax[0][j - 1] * grid[0][j];
            leftMin[0][j] = leftMin[0][j - 1] * grid[0][j];
        }

        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                long maxUp = Math.max(upMax[i - 1][j], upMin[i - 1][j]);
                long minUp = Math.min(upMax[i - 1][j], upMin[i - 1][j]);

                long maxLeft = Math.max(leftMax[i][j - 1], leftMin[i][j - 1]);
                long minLeft = Math.min(leftMax[i][j - 1], leftMin[i][j - 1]);

                if (grid[i][j] < 0) {
                    upMax[i][j] = Math.max(minUp * grid[i][j], maxLeft * grid[i][j]);
                    upMin[i][j] = Math.min(maxUp * grid[i][j], minLeft * grid[i][j]);

                    leftMax[i][j] = Math.max(minLeft * grid[i][j], maxUp * grid[i][j]);
                    leftMin[i][j] = Math.min(maxLeft * grid[i][j], minUp * grid[i][j]);
