public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numWays(String s) {
        int ones = 0;
        for (char c : s.toCharArray()) {
            if (c == '1') {
                ones++;
            }
        }

        if (ones % 3 != 0) {
            return 0;
        }

        if (ones == 0) {
            long res = 1;
            int zeros = 0;
            for (char c : s.toCharArray()) {
                if (c == '0') {
                    zeros++;
                } else {
                    res = res * (zeros + 1) % MOD;
                    zeros = 0;
                }
            }
            return (int) ((res * (zeros + 1)) % MOD);
        }

        int targetOnes = ones / 3;
        int leftZeros = 0, rightZeros = 0;
        int leftOnes = 0, rightOnes = 0;
        for (char c : s.toCharArray()) {
            if (c == '1') {
                leftOnes++;
                rightOnes--;
            } else {
                leftZeros++;
                rightZeros--;
            }

            if (leftOnes == targetOnes && leftZeros >= 0) {
                int rightTarget = ones - leftOnes;
                if (rightOnes == rightTarget && rightZeros >= 0) {
                    return (int) ((long) (leftZeros + 1) * (rightZeros + 1) % MOD);
                }
            }
        }

        return 0;
    }
}

