// #Hard #String #Dynamic_Programming #2022_04_09_Time_34_ms_(83.91%)_Space_54.2_MB_(25.65%)
public class Solution {
    public int getLengthOfOptimalCompression(String s, int k) {
        int n = s.length();
        int[][] dp = new int[n + 1][k + 1];
        for (int[] row : dp) Arrays.fill(row, Integer.MAX_VALUE / 2);
        dp[0][0] = 0;

        for (int i = 1; i <= n; ++i) {
            int count = 0;
            for (int j = i - 1; j >= 0 && i - j - 1 <= k; --j) {
                if (s.charAt(j) == s.charAt(i - 1)) ++count;
                int delete = i - j - 1;
                int keep = count > 0 ? (count < 10 ? 1 : (count < 100 ? 2 : 3)) : 0;
                for (int m = 0; m <= k - delete; ++m) {
                    dp[i][delete + m] = Math.min(dp[i][delete + m], dp[j][m] + keep);
                }
            }
        }

        int res = Integer.MAX_VALUE / 2;
        for (int i = 0; i <= k; ++i) res = Math.min(res, dp[n][i]);
        return res;
    }
}

