// #Medium #Array #Depth_First_Search #Breadth_First_Search #Matrix #Union_Find
// #2022_04_11_Time_22_ms_(82.51%)_Space_135.8_MB_(70.24%)
public class Solution {
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    public boolean containsCycle(char[][] grid) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (dfs(grid, i, j, -1, -1, new HashSet<>())) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean dfs(char[][] grid, int x, int y, int prevX, int prevY, Set<String> visited) {
        if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length
                || grid[x][y] != grid[prevX][prevY]) {
            return false;
        }

        String key = x + "," + y;
        if (visited.contains(key)) {
            return true;
        }
        visited.add(key);

        for (int[] direction : DIRECTIONS) {
            int newX = x + direction[0];
            int newY = y + direction[1];

            if ((newX != prevX || newY != prevY) && dfs(grid, newX, newY, x, y, visited)) {
                return true;
            }
        }

        visited.remove(key);
        return false;
    }
}

