public class Solution {
    public int minCost(int n, int[] cuts) {
        Arrays.sort(cuts);
        int len = cuts.length;
        int[][] dp = new int[len + 1][len + 1];

        for (int d = 2; d <= len + 1; d++) {
            for (int i = 0; i < len - d + 1; i++) {
                int j = i + d - 1;
