public class Solution {
    private static final int MOD = (int) 1e9 + 7;
    private Map<String, Long> memo;

    public int countRoutes(int[] locations, int start, int finish, int fuel) {
        memo = new HashMap<>();
        return (int) dfs(locations, start, finish, fuel);
    }

    private long dfs(int[] locations, int currentCity, int finish, int remainingFuel) {
        if (remainingFuel < 0) {
            return 0;
        }
        String key = currentCity + "," + remainingFuel;
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        long result = currentCity == finish ? 1 : 0;

        for (int i = 0; i < locations.length; i++) {
            if (i != currentCity) {
                int fuelConsumed = Math.abs(locations[currentCity] - locations[i]);
                result += dfs(locations, i, finish, remainingFuel - fuelConsumed);
                result %= MOD;
            }
        }

        memo.put(key, result);
        return result;
    }
}

