            }
        }

        long diff = Math.abs(sum1 - sum2);

        if (diff > zeroCount1 + zeroCount2) {
            return -1;
        }

        long minSum = sum1 + sum2 + diff;

        if ((zeroCount1 + zeroCount2) % 2 == 0 && diff != 0) {
            minSum -= diff;
        }

        return minSum;
    }
}

