import java.util.Arrays;

public class Solution {
    public int maxNumEdgesToRemove(int n, int[][] edges) {
        UnionFind alice = new UnionFind(n);
        UnionFind bob = new UnionFind(n);

        int remove = 0;
        for (int[] edge : edges) {
            if (edge[0] == 3 && !alice.union(edge[1], edge[2])) {
                remove++;
            }
        }

        for (int[] edge : edges) {
            if (edge[0] == 1 && !alice.union(edge[1], edge[2])) {
                remove++;
            } else if (edge[0] == 2 && !bob.union(edge[1], edge[2])) {
                remove++;
            }
        }

        if (alice.count() != 1 || bob.count() != 1) return -1;

        return remove;
    }

    class UnionFind {
        int[] parent, rank;
        int count;

        public UnionFind(int n) {
            parent = new int[n + 1];
            rank = new int[n + 1];
            for (int i = 0; i <= n; i++) {
                parent[i] = i;
            }
            count = n;
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public boolean union(int x, int y) {
            int rootx = find(x);
            int rooty = find(y);
            if (rootx == rooty) return false;
            if (rank[rootx] > rank[rooty]) {
                parent[rooty] = rootx;
            } else if (rank[rootx] < rank[rooty]) {
                parent[rootx] = rooty;
            } else {
                parent[rooty] = rootx;
                rank[rootx]++;
            }
            count--;
            return true;
        }

        public int count() {
            return count;
        }
    }
}

