import java.util.*;

public class Solution {
    public List<String> getWordsInLongestSubsequence(int n, String[] words, int[] groups) {
        Map<Integer, List<Integer>> groupMap = new HashMap<>();
        for (int i = 0; i < n; i++) {
            groupMap.computeIfAbsent(groups[i], k -> new ArrayList<>()).add(i);
        }

        Map<String, Integer> wordLengthMap = new HashMap<>();
        for (String word : words) {
            wordLengthMap.put(word, word.length());
        }

        int[] dp = new int[n];
        Arrays.fill(dp, 1);

        List<Integer>[] prevIndex = new List[n];
        for (int i = 0; i < n; i++) {
            prevIndex[i] = new ArrayList<>();
        }

        for (int i = 0; i < n; i++) {
            for (int j : groupMap.getOrDefault(groups[i], Collections.emptyList())) {
                if (i == j) continue;
                if (wordLengthMap.get(words[j]) != wordLengthMap.get(words[i])) continue;

                int hammingDistance = getHammingDistance(words[i], words[j]);
                if (hammingDistance != 1) continue;

                if (dp[j] + 1 > dp[i]) {
                    dp[i] = dp[j] + 1;
                    prevIndex[i].clear();
                    prevIndex[i].add(j);
                } else if (dp[j] + 1 == dp[i]) {
                    prevIndex[i].add(j);
                }
            }
        }

        int maxIndex = -1;
        for (int i = 0; i < n; i++) {
            if (maxIndex == -1 || dp[maxIndex] < dp[i]) {
                maxIndex = i;
            }
        }

        List<String> result = new ArrayList<>();
        while (maxIndex != -1) {
            result.add(words[maxIndex]);
            int nextIndex = prevIndex[maxIndex].isEmpty() ? -1 : prevIndex[maxIndex].get(0);
            for (int index : prevIndex[maxIndex]) {
                if (dp[index] > dp[nextIndex]) {
                    nextIndex = index;
                }
            }
            maxIndex = nextIndex;
        }

        Collections.reverse(result);
        return result;
    }

    private int getHammingDistance(String s1, String s2) {
        int distance = 0;
        for (int i = 0; i < s1.length(); i++) {
            if (s1.charAt(i) != s2.charAt(i)) {
                distance++;
            }
        }
        return distance;
    }
}

