public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numberOfGoodPartitions(int[] nums, int k) {
        return numberOfGoodPartitions(nums);
    }

    public int numberOfGoodPartitions(int[] nums) {
        Map<Integer, Integer> countMap = new HashMap<>();
        for (int num : nums) {
            countMap.put(num, countMap.getOrDefault(num, 0) + 1);
        }

        long res = 0;
        int n = nums.length;
        boolean[] dp = new boolean[n + 1];
        dp[0] = true;

        for (int i = 1; i <= n; i++) {
            if (countMap.get(nums[i - 1]) > 1) {
                break;
            }
            int j = i;
            while (j >= 1 && countMap.get(nums[j - 1]) == 1) {
                dp[i] |= dp[i - j];
                j--;
            }
            if (dp[i]) {
                res += pow(2, n - i);
                res %= MOD;
            }
        }

        return (int) res;
    }

    private long pow(long a, int b) {
        long res = 1;
        while (b > 0) {
            if ((b & 1) == 1) {
                res = res * a % MOD;
            }
            a = a * a % MOD;
            b >>= 1;
        }
        return res;
    }
}

