public class Solution {
    public int findMaximumLength(int[] nums) {
        int n = nums.length;
        long[] prefixSum = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + nums[i];
        }

        int[][] dp = new int[n][n];
        for (int j = 0; j < n; j++) {
            dp[j][j] = 1;
            if (j > 0 && nums[j - 1] <= nums[j]) {
                dp[j - 1][j] = 2;
            }
        }

        int maxLen = 1;
        for (int len = 3; len <= n; len++) {
            for (int i = 0, j = len - 1; j < n; i++, j++) {
                if (nums[i] > prefixSum[j + 1] - prefixSum[i]) continue;

                int maxSubLen = 0;
                for (int k = i; k <= j - 2; k++) {
                    if (dp[k][j - 1] == 0 || nums[k] > prefixSum[j] - prefixSum[k + 1]) continue;
                    maxSubLen = Math.max(maxSubLen, dp[i][k]);
                }
                dp[i][j] = maxSubLen + 1;
                if (dp[i][j] >= len) {
                    maxLen = len;
                }
            }
        }

        return maxLen;
    }
}

