public class Solution {
    public long minIncrementOperations(int[] nums, int k) {
        int n = nums.length;
        long res = 0;
        for (int i = 1; i < n; ++i) {
            if (nums[i] < nums[i - 1]) {
                int diff = nums[i - 1] + 1 - nums[i];
                res += diff;
                nums[i] += diff;
            }
        }

        long max = nums[n - 1], sum = nums[n - 1];
        for (int i = n - 2; i >= 0; --i) {
            if (nums[i] > max) {
                max = nums[i];
            } else if (max < k && nums[i] + k <= max) {
                long diff = max - nums[i];
                res += diff;
                sum += diff * (n - i);
            }
        }

        return Math.max(res, Math.ceil((double)(k - max)) + sum / (n + 1));
    }
}

