    private static final int MOD = (int) 1e9 + 7;

    public int countGoodStrings(int n) {
        long[] dp = new long[n / 4 + 2];
        dp[0] = 1;

        for (int i = 1; i <= n; i++) {
            if (i >= 4) {
                dp[i % 4] += dp[(i - 4) % 4];
            }
            if (i >= 5) {
                dp[i % 4] += dp[(i - 5) % 4];
            }
            dp[i % 4] %= MOD;
        }

        long res = 0;
        for (int i = n / 4; i <= n && i <= 4; i++) {
            if (n - i >= 0) {
                res += dp[n - i];
            }
        }
        return (int) (res % MOD);
    }
}

