public class Solution {
    public long maximumScoreAfterOperations(int[][] edges, int[] values) {
        int n = values.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        long[][] dp = new long[n][2];
        dfs(graph, values, 0, -1, dp);

        return Math.max(dp[0][0], dp[0][1]);
    }

    private void dfs(List<Integer>[] graph, int[] values, int node, int parent, long[][] dp) {
        if (graph[node].size() == 1 && graph[node].get(0) == parent) {
            dp[node][0] = values[node];
            dp[node][1] = -values[node];
            return;
        }

        for (int child : graph[node]) {
            if (child != parent) {
                dfs(graph, values, child, node, dp);
            }
        }

        long sumZero = 0;
        long sumNonZero = Long.MIN_VALUE;
        for (int child : graph[node]) {
            if (child != parent) {
                sumZero += Math.max(dp[child][0], dp[child][1]);
                sumNonZero = Math.max(sumNonZero, dp[child][0] - dp[child][1]);
            }
        }

        dp[node][0] = values[node] + sumZero;
        dp[node][1] = -values[node] + sumZero + sumNonZero;
    }
}

