public class Solution {
    public int minimumChanges(String s, int k) {
        int n = s.length();
        int[][] dp = new int[n + 1][k + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                dp[i][j] = Integer.MAX_VALUE;
            }
        }
        dp[0][0] = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= Math.min(i, k); j++) {
                int changes = getChanges(s.substring(0, i), j);
                dp[i][j] = Math.min(dp[i][j], dp[i - j][j - 1] + changes);
            }
        }

        return dp[n][k];
    }

    private int getChanges(String s, int k) {
        int n = s.length();
        if (n % k != 0) {
            return Integer.MAX_VALUE;
        }
        int d = n / k;

        for (int i = 0; i < d; i++) {
            char c = ' ';
            int count = 0;
            for (int j = 0; j < k; j++) {
                if (s.charAt(i + j * d) != s.charAt(n - 1 - i - j * d)) {
                    count++;
                }
                if (c == ' ') {
                    c = s.charAt(i + j * d);
                } else if (c != s.charAt(i + j * d) && c != s.charAt(n - 1 - i - j * d)) {
                    return Integer.MAX_VALUE;
                }
            }
            if (count > 0) {
                count /= 2;
            }
        }

        return n / k;
    }
}

