public class Solution {
    public boolean areSimilar(int[][] mat, int k) {
        int m = mat.length;
        int n = mat[0].length;

        // Create a copy of the original matrix
        int[][] originalMat = new int[m][n];
        for (int i = 0; i < m; i++) {
            System.arraycopy(mat[i], 0, originalMat[i], 0, n);
        }

        // Perform cyclic shifts on the rows
        for (int i = 0; i < m; i++) {
            int shift = k % n;
            if (i % 2 == 0) { // even indexed row, left shift
                System.arraycopy(mat[i], shift, mat[i], 0, n - shift);
                System.arraycopy(mat[i], 0, mat[i], n - shift, shift);
            } else { // odd indexed row, right shift
                System.arraycopy(mat[i], n - shift, mat[i], 0, shift);
                System.arraycopy(mat[i], 0, mat[i], shift, n - shift);
            }
        }

        // Compare the original and modified matrices
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (originalMat[i][j] != mat[i][j]) {
                    return false;
                }
            }
        }

        return true;
    }
}

