public class Solution {
    public int minOperations(int[] nums, int k) {
        int xor = 0;
        for (int num : nums) {
            xor ^= num;
        }

        if (xor == k) return 0;

        int n = nums.length;
        int[][] dp = new int[n + 1][k + 1];
        for (int[] row : dp) {
            java.util.Arrays.fill(row, Integer.MAX_VALUE);
        }
        dp[0][0] = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                if (dp[i - 1][j] != Integer.MAX_VALUE) {
                    int curr = nums[i - 1];
                    dp[i][j] = Math.min(dp[i][j], dp[i - 1][j] + getFlips(curr, j));

                    if ((curr ^ j) < k) {
                        dp[i][curr ^ j] = Math.min(dp[i][curr ^ j], dp[i - 1][j]);
                    }
                }
            }
        }

        int res = Integer.MAX_VALUE;
        for (int i = 0; i <= k; i++) {
            if ((i ^ xor) == k) {
                res = Math.min(res, dp[n][i]);
            }
        }

        return res == Integer.MAX_VALUE ? -1 : res;
    }

    private int getFlips(int num, int target) {
        int flips = 0;
        for (int i = 0; i < 32; i++) {
            if (((num >> i) & 1) != ((target >> i) & 1)) {
                flips++;
            }
        }
        return flips;
    }
}

