public class Solution {
    public int maximizeSquareHoleArea(int n, int m, int[] hBars, int[] vBars) {
        Arrays.sort(hBars);
        Arrays.sort(vBars);

        int maxH = 0;
        for (int i = 1; i <= n + 1; i++) {
            if (!binarySearch(hBars, i)) {
                maxH = Math.max(maxH, findMaxConsecutive(i, hBars));
            }
        }

        int maxV = 0;
        for (int j = 1; j <= m + 1; j++) {
            if (!binarySearch(vBars, j)) {
                maxV = Math.max(maxV, findMaxConsecutive(j, vBars));
            }
        }

        return maxH * maxV;
    }

    private boolean binarySearch(int[] arr, int target) {
        int left = 0;
        int right = arr.length - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] == target) return true;
            else if (arr[mid] < target) left = mid + 1;
            else right = mid - 1;
        }

        return false;
    }

    private int findMaxConsecutive(int start, int[] arr) {
        int maxCount = 0;
        int count = 0;

        for (int i = start; i <= arr[arr.length - 1]; i++) {
            if (!binarySearch(arr, i)) {
                count++;
                maxCount = Math.max(maxCount, count);
            } else {
                count = 0;
            }
        }

        return maxCount;
    }
}

