import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int[] closestRoom(int[] heights, int[][] queries) {
        // Create a new array to store the indices and values of the heights array
        Integer[][] heightIndices = new Integer[heights.length][2];

        for (int i = 0; i < heights.length; i++) {
            heightIndices[i] = new Integer[] {i, heights[i]};
        }

        // Sort the heightIndices array based on the values in descending order
        Arrays.sort(heightIndices, new Comparator<Integer[]>() {
            @Override
            public int compare(Integer[] a, Integer[] b) {
                return b[1].compareTo(a[1]);
            }
        });

        int[] result = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            // Find the first index in heightIndices where the value is greater than or equal to the query's value
            int left = 0, right = heights.length - 1;
            while (left <= right) {
                int mid = left + (right - left) / 2;
                if (heightIndices[mid][1] >= heights[queries[i][1]]) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }

            // If no such index is found, set the result to -1
            if (left == 0) {
                result[i] = -1;
            } else {
                // Otherwise, find the leftmost building where Alice and Bob can meet
                int minIndex = Integer.MAX_VALUE;
                for (int j = left - 1; j >= 0; j--) {
                    if (heightIndices[j][1] > heights[queries[i][0]]) {
                        minIndex = Math.min(minIndex, heightIndices[j][0]);
                    }
                }

                // If no such building is found, set the result to -1
                if (minIndex == Integer.MAX_VALUE) {
                    result[i] = -1;
                } else {
                    result[i] = minIndex;
                }
            }
        }

        return result;
    }
}

