// #Hard #Dynamic_Programming #Sorting #Depth_First_Search #Tree #Heap_Priority_Queue
// #2024_01_16_Time_93_ms_(72.11%)_Space_63.4_MB_(33.51%)
public class Solution {
    public long[] placedCoins(int[][] edges, int[] cost) {
        int n = cost.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        long[] res = new long[n];
        dfs(graph, cost, 0, -1, res);
        return res;
    }

    private long[] dfs(List<Integer>[] graph, int[] cost, int node, int parent, long[] res) {
        PriorityQueue<Integer> pq = new PriorityQueue<>(Comparator.reverseOrder());
        List<long[]> subtreeRes = new ArrayList<>();

        for (int child : graph[node]) {
            if (child == parent) continue;
            long[] childRes = dfs(graph, cost, child, node, res);
            subtreeRes.add(childRes);
            pq.offer(cost[child]);
            if (pq.size() > 3) pq.poll();
        }

        int size = 1 + subtreeRes.stream().mapToInt(x -> x.length).sum();

        long maxProduct = 0;
        if (!pq.isEmpty()) {
            maxProduct = Math.max(maxProduct, (long) cost[node] * pq.peek());
            if (pq.size() > 1) {
                int second = pq.poll();
                maxProduct = Math.max(maxProduct, (long) cost[node] * pq.peek() * second);
                pq.offer(second);
            }
        }

        long[] currentRes = new long[size];
        currentRes[0] = res[node] = Math.max(1, maxProduct > 0 ? maxProduct : 0);

        int index = 1;
        for (long[] childRes : subtreeRes) {
            System.arraycopy(childRes, 0, currentRes, index, childRes.length);
            index += childRes.length;
        }

        return currentRes;
    }
}

