import java.util.Arrays;
public class Solution {
    public long minimumCost(int[] nums) {
        Arrays.sort(nums);
        int n = nums.length;
        int median = nums[n / 2];

        if (String.valueOf(median).equals(new StringBuilder(String.valueOf(median)).reverse().toString())) {
            return calculateCost(nums, median);
        } else {
            long cost1 = calculateCost(nums, getPreviousPalindrome(median));
            long cost2 = calculateCost(nums, getNextPalindrome(median));
            return Math.min(cost1, cost2);
        }
    }

    private int getPreviousPalindrome(int num) {
        String strNum = String.valueOf(num - 1);
        StringBuilder sb = new StringBuilder(strNum).reverse();
        while (!strNum.equals(sb.toString())) {
            num--;
            strNum = String.valueOf(num);
            sb = new StringBuilder(strNum).reverse();
        }
        return num;
    }

    private int getNextPalindrome(int num) {
        String strNum = String.valueOf(num + 1);
        StringBuilder sb = new StringBuilder(strNum).reverse();
        while (!strNum.equals(sb.toString())) {
            num++;
            strNum = String.valueOf(num);
            sb = new StringBuilder(strNum).reverse();
        }
        return num;
    }

    private long calculateCost(int[] nums, int target) {
        long cost = 0;
        for (int num : nums) {
            cost += Math.abs(target - num);
        }
        return cost;
    }
}

