import java.util.Map;

public class Solution {
    public boolean[] canMakePaliQueries(String s, int[][] queries) {
        int n = s.length();
        Map<Character, Integer>[] freqs = new Map[n / 2 + 1];
        for (int i = 0; i <= n / 2; i++) {
            freqs[i] = new HashMap<>();
            for (int j = 0; j < i; j++) {
                char c = s.charAt(j);
                freqs[i].put(c, freqs[i].getOrDefault(c, 0) + 1);
            }
        }

        boolean[] res = new boolean[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int a = queries[i][0], b = queries[i][1], c = queries[i][2], d = queries[i][3];

            Map<Character, Integer> leftFreqs = getFreqs(freqs, s, a, b);
            Map<Character, Integer> rightFreqs = getFreqs(freqs, s, c, d);

            res[i] = canMakePali(leftFreqs, rightFreqs);
        }

        return res;
    }

    private Map<Character, Integer> getFreqs(Map<Character, Integer>[] freqs, String s, int start, int end) {
        if (start == 0) {
            return freqs[end + 1];
        } else {
            Map<Character, Integer> left = new HashMap<>(freqs[start]);
            for (int i = start; i <= end; i++) {
                char c = s.charAt(i);
                left.put(c, left.getOrDefault(c, 0) + 1);
            }
            return left;
        }
    }

    private boolean canMakePali(Map<Character, Integer> leftFreqs, Map<Character, Integer> rightFreqs) {
        int diffCount = 0;
        for (char c : leftFreqs.keySet()) {
            if (!rightFreqs.containsKey(c)) {
                diffCount++;
            } else if (leftFreqs.get(c) != rightFreqs.get(c)) {
                diffCount += Math.abs(leftFreqs.get(c) - rightFreqs.get(c));
            }
        }

        return diffCount <= 1;
    }
}

