public class Solution {
    public int[][] divideArray(int[] nums, int k) {
        Arrays.sort(nums);
        int n = nums.length;
        if (n % 3 != 0) return new int[0][];

        int[][] res = new int[n / 3][3];
        for (int i = 0; i < n; i += 3) {
            if (nums[i + 2] - nums[i] > k) return new int[0][];
            res[i / 3] = Arrays.copyOfRange(nums, i, i + 3);
        }

        return res;
    }
}

