public class Solution {
    public long minimumSteps(String s) {
        int n = s.length();
        int leftWhite = 0;
        int rightBlack = 0;

        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '1') {
                rightBlack++;
            } else {
                leftWhite++;
            }
        }

        long res = Long.MAX_VALUE;

        int whiteCount = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '0') {
                whiteCount++;
            } else {
                rightBlack--;
            }

            long steps = leftWhite - whiteCount + rightBlack;
            res = Math.min(res, steps);
        }

        return res;
    }
}

