public class Solution {
    public long maxBalancedSubsequenceSum(int[] nums) {
        int n = nums.length;
        Map<Integer, Long> dp = new HashMap<>();
        long res = 0;

        for (int i = 0; i < n; i++) {
            long curMax = nums[i];
            for (Map.Entry<Integer, Long> entry : dp.entrySet()) {
                int diff = i - entry.getKey();
                if (nums[i] - entry.getValue() >= diff) {
                    curMax = Math.max(curMax, nums[i] + entry.getValue());
                }
            }
            res = Math.max(res, curMax);
            dp.put(i, curMax);
        }

        return res;
    }
}

