public class Solution {
    public int[][] constructProductMatrix(int[][] grid) {
        int n = grid.length;
        int m = grid[0].length;

        long totalProduct = 1;
        int zeroCount = 0;

        // Calculate total product and count of zeros
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 0) {
                    zeroCount++;
                } else {
                    totalProduct *= grid[i][j];
                    totalProduct %= 1000000007;
                }
            }
        }

        int[][] result = new int[n][m];

        // Calculate product for each cell
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (zeroCount > 1) {
                    result[i][j] = 0;
                } else if (zeroCount == 1) {
                    result[i][j] = grid[i][j] == 0 ? totalProduct : 0;
                } else {
                    result[i][j] = (int)(totalProduct * pow(grid[i][j], -1, 1000000007));
                }
            }
        }

        return result;
    }

    // Function to calculate modular inverse using Fermat's Little Theorem
    private long pow(long a, int b, int mod) {
        if (b == 0) return 1;
        long temp = pow(a, b / 2, mod);
        temp = (temp * temp) % mod;
        if ((b & 1) != 0) temp = (temp * a) % mod;
        return temp;
    }
}

