import java.util.Set;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int maxArea(int m, int n, int[] hFences, int[] vFences) {
        Arrays.sort(hFences);
        Arrays.sort(vFences);

        Set<Integer> hSet = new HashSet<>();
        for (int fence : hFences) {
            hSet.add(fence);
        }

        Set<Integer> vSet = new HashSet<>();
        for (int fence : vFences) {
            vSet.add(fence);
        }

        int maxHGap = getMaxGap(hSet, m);
        int maxVGap = getMaxGap(vSet, n);

        long res = Math.min(maxHGap, maxVGap);
        return (int) (res * res % MOD);
    }

    private int getMaxGap(Set<Integer> set, int limit) {
        int prev = 1;
        int maxGap = 0;

        for (Integer num : set) {
            if (!set.contains(prev)) {
                maxGap = Math.max(maxGap, num - prev);
            }
            prev = num + 1;
        }

        return Math.max(maxGap, limit - prev + 1);
    }
}

