// #2024_01_17_Time_0_ms_(100.00%)_Space_41.2_MB_(92.39%)
public class Solution {
    public int minimumOperationsToMakeEqual(int x, int y) {
        if (x == y) return 0;

        Queue<Integer> queue = new LinkedList<>();
        boolean[] visited = new boolean[2000001];

        queue.offer(x);
        visited[x] = true;
        int step = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();

            for (int i = 0; i < size; i++) {
                int current = queue.poll();

                if (current == y) return step;

                if (current % 11 == 0 && !visited[current / 11]) {
                    queue.offer(current / 11);
                    visited[current / 11] = true;
                }

                if (current % 5 == 0 && !visited[current / 5]) {
                    queue.offer(current / 5);
                    visited[current / 5] = true;
                }

                if (!visited[current - 1]) {
                    queue.offer(current - 1);
                    visited[current - 1] = true;
                }

                if (current + 1 <= 2000000 && !visited[current + 1]) {
                    queue.offer(current + 1);
                    visited[current + 1] = true;
                }
            }

            step++;
        }

        return -1; // This line will never be reached
    }
}

