public class Solution {
    public long numberOfPowerfulInt(long start, long finish, int limit, String s) {
        char[] suffix = s.toCharArray();
        long res = 0;
        for (long i = start; i <= finish; i++) {
            if (isSuffix(i, suffix) && isLimited(i, limit)) {
                res++;
            }
        }
        return res;
    }

    private boolean isSuffix(long num, char[] suffix) {
        String strNum = Long.toString(num);
        int lenDiff = strNum.length() - suffix.length;
        if (lenDiff < 0) return false;
        for (int i = 0; i < suffix.length; i++) {
            if (strNum.charAt(lenDiff + i) != suffix[i]) return false;
        }
        return true;
    }

    private boolean isLimited(long num, int limit) {
        String strNum = Long.toString(num);
        for (char c : strNum.toCharArray()) {
            if (c - '0' > limit) return false;
        }
        return true;
    }
}

