import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int collectTheCoins(int[][] edges, int[] coins, int k) {
        int n = coins.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        int[] subtreeCoins = new int[n];
        dfs(graph, coins, subtreeCoins, 0, -1);

        long[][] dp = new long[n][2];
        for (long[] row : dp) {
            row[0] = Long.MIN_VALUE / 2;
            row[1] = Long.MIN_VALUE / 2;
        }

        dfs2(graph, coins, subtreeCoins, dp, k, 0, -1);

        return Math.max((int)dp[0][0], (int)dp[0][1]);
    }

    private void dfs(List<Integer>[] graph, int[] coins, int[] subtreeCoins, int node, int parent) {
        for (int child : graph[node]) {
            if (child == parent) continue;
            dfs(graph, coins, subtreeCoins, child, node);
            subtreeCoins[node] += subtreeCoins[child];
        }
        subtreeCoins[node] += coins[node];
    }

    private void dfs2(List<Integer>[] graph, int[] coins, int[] subtreeCoins, long[][] dp, int k, int node, int parent) {
        for (int child : graph[node]) {
            if (child == parent) continue;
            dfs2(graph, coins, subtreeCoins, dp, k, child, node);
        }

        // collect all
        dp[node][0] = Math.max(dp[node][0], (coins[node] - k + subtreeCoins[node] / 2));

        // collect half
        long sum = 0;
        for (int child : graph[node]) {
            if (child == parent) continue;
            sum += Math.max(dp[child][0], dp[child][1]);
        }
        dp[node][1] = Math.max(dp[node][1], coins[node] / 2 + sum);
    }
}

