// #Medium #Array #Heap_Priority_Queue #Simulation
// #2024_03_31_Time_26_ms_(99.91%)_Space_65.7_MB_(97.28%)
public class Solution {
    public int minOperations(int[] nums, int k) {
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int num : nums) {
            if (num < k) {
                pq.offer(num);
            }
        }

        int operations = 0;
        while (!pq.isEmpty()) {
            int x = pq.poll();
            if (pq.isEmpty()) break;
            int y = pq.poll();

            int minVal = Math.min(x, y);
            int maxVal = Math.max(x, y);

            int newVal = minVal * 2 + maxVal;

            operations++;
            if (newVal < k) {
                pq.offer(newVal);
            }
        }

        return operations;
    }
}

