    public String minimizeStringValue(String s) {
        int n = s.length();
        char[] chars = s.toCharArray();

        for (int i = 0; i < n; i++) {
            if (chars[i] == '?') {
                boolean[] seen = new boolean[26];
                for (int j = 0; j < i; j++) {
                    if (chars[j] >= 'a' && chars[j] <= 'z') {
                        seen[chars[j] - 'a'] = true;
                    }
                }

                int idx = 0;
                while (idx < 26 && seen[idx]) {
                    idx++;
                }

                chars[i] = (char) ('a' + idx);
            }
        }

        return new String(chars);
    }
}

