public class Solution {
    public int minimumLevels(int[] possible) {
        int alice = 0, bob = 0;
        for (int i : possible) {
            if (i == 1) {
                alice++;
            } else {
                break;
            }
        }

        for (int i = possible.length - 1; i >= 0; i--) {
            if (possible[i] == 1) {
                bob++;
            } else {
                break;
            }
        }

        int minLevels = Math.min(alice, bob);
        return alice > bob ? minLevels : -1;
    }
}

