// #Medium #Array #Hash_Table #Sorting #Heap_Priority_Queue #Simulation
// #2024_04_16_Time_50_ms_(99.96%)_Space_77.2_MB_(15.35%)
public class Solution {
    public long[] unmarkedSumArray(int[] nums, int[][] queries) {
        int n = nums.length;
        int m = queries.length;

        // Create a priority queue to store the indices of unmarked elements
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] == b[0] ? a[1] - b[1] : a[0] - b[0]);
        for (int i = 0; i < n; i++) {
            pq.offer(new int[] {nums[i], i});
        }

        // Create an array to store the result
        long[] res = new long[m];

        // Initialize the sum of all elements in nums
        long sum = 0;
        for (int num : nums) {
            sum += num;
        }

        // Marked set to keep track of marked indices
        Set<Integer> marked = new HashSet<>();

        for (int i = 0; i < m; i++) {
            int index = queries[i][0];
            int k = queries[i][1];

            // Mark the element at index if it's not already marked
            if (!marked.contains(index)) {
                sum -= nums[index];
                marked.add(index);
            }

            // Mark k unmarked elements with the smallest values
            for (int j = 0; j < k && !pq.isEmpty(); j++) {
                int[] top = pq.poll();
                if (!marked.contains(top[1])) {
                    sum -= top[0];
                    marked.add(top[1]);
                }
            }

            // Update the result array
            res[i] = sum;
        }

        return res;
    }
}

