public class Solution {
    public int minOrAfterOperations(int[] nums, int k) {
        int n = nums.length;
        int[][] dp = new int[n][n];

        // Initialize dp array with bitwise OR of subarrays
        for (int i = 0; i < n; i++) {
            dp[i][i] = nums[i];
            if (i + 1 < n) {
                dp[i][i + 1] = nums[i] | nums[i + 1];
            }
        }

        // Fill up the rest of the dp array
        for (int len = 3; len <= n; len++) {
            for (int i = 0; i < n - len + 1; i++) {
                int j = i + len - 1;
                dp[i][j] = nums[i];
                for (int mid = i; mid < j; mid++) {
                    dp[i][j] |= dp[mid + 1][j];
                }
            }
        }

        // Find the minimum possible value of bitwise OR
        int minOr = Integer.MAX_VALUE;
        for (int i = 0; i < n - k; i++) {
            minOr = Math.min(minOr, dp[i][i + k]);
        }

        return minOr;
    }
}

