public class Solution {
    public long countPrefixSuffixPairs(String[] words) {
        int n = words.length;
        long res = 0;

        for (int i = 0; i < n; i++) {
            String word1 = words[i];
            for (int j = i + 1; j < n; j++) {
                String word2 = words[j];

                if (word1.length() > word2.length()) continue;

                boolean isPrefix = true, isSuffix = true;

                for (int k = 0; k < word1.length(); k++) {
                    if (word1.charAt(k) != word2.charAt(k)) {
                        isPrefix = false;
                        break;
                    }
                }

                for (int k = 0; k < word1.length(); k++) {
                    if (word1.charAt(word1.length() - 1 - k) != word2.charAt(word2.length() - 1 - k)) {
                        isSuffix = false;
                        break;
                    }
                }

                if (isPrefix && isSuffix) res++;
            }
        }

        return res;
    }
}

