import java.util.*;

public class Solution {
    public List<Integer> beautifulIndices(String s, String a, String b, int k) {
        List<Integer> result = new ArrayList<>();
        Deque<Integer> indicesA = findIndices(s, a);
        Deque<Integer> indicesB = findIndices(s, b);

        while (!indicesA.isEmpty() && !indicesB.isEmpty()) {
            if (Math.abs(indicesA.peekFirst() - indicesB.peekFirst()) <= k) {
                result.add(indicesA.pollFirst());
                indicesB.pollFirst();
            } else if (indicesA.peekFirst() < indicesB.peekFirst()) {
                indicesA.pollFirst();
            } else {
                indicesB.pollFirst();
            }
        }

        Collections.sort(result);
        return result;
    }

    private Deque<Integer> findIndices(String s, String target) {
        Deque<Integer> indices = new ArrayDeque<>();
        for (int i = 0; i <= s.length() - target.length(); i++) {
            if (s.substring(i, i + target.length()).equals(target)) {
                indices.addLast(i);
            }
        }
        return indices;
    }
}

