public class Solution {
    public int minimumTimeToInitialState(String word, int k) {
        final int MOD = (int) 1e9 + 7;
        final long BASE = 113;

        int n = word.length();
        long[] pow = new long[n + 1];
        pow[0] = 1;
        for (int i = 1; i <= n; i++) {
            pow[i] = pow[i - 1] * BASE % MOD;
        }

        long hash = 0;
        for (char c : word.toCharArray()) {
            hash = (hash * BASE + c) % MOD;
        }

        int res = Integer.MAX_VALUE;
        for (int i = k; i <= n; i++) {
            long newHash = ((hash - pow[i] * word.charAt(i - k)) % MOD + MOD) % MOD;
            if (newHash == hash) {
                res = Math.min(res, i);
            }
            hash = (hash * BASE + word.charAt(i % n)) % MOD;
        }

        return res > n ? -1 : res / k;
    }
}

