public class Solution {
    public int shortestSubarray(int[] nums, int k) {
        int n = nums.length;
        long[] prefixSum = new long[n + 1];

        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] | nums[i];
        }

        int res = Integer.MAX_VALUE;
        for (int left = 0; left < n; left++) {
            if ((prefixSum[left] & k) == k) {
                res = Math.min(res, left);
            } else {
                int right = binarySearch(prefixSum, prefixSum[left], k, left + 1, n);
                if (right != -1) {
                    res = Math.min(res, right - left);
                }
            }
        }

        return res == Integer.MAX_VALUE ? -1 : res;
    }

    private int binarySearch(long[] prefixSum, long target, int k, int left, int right) {
        while (left < right) {
            int mid = left + (right - left) / 2;
            if ((prefixSum[mid] | target) >= k) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        return left == prefixSum.length || (prefixSum[left] | target) < k ? -1 : left;
    }
}

