public class Solution {
    public int countMatchingSubarrays(int[] nums, int[] pattern) {
        int n = nums.length;
        int m = pattern.length;
        int res = 0;

        for (int i = 0; i <= n - m - 1; i++) {
            boolean match = true;

            for (int j = 0; j < m; j++) {
                if ((pattern[j] == 0 && nums[i + j + 1] != nums[i + j]) ||
                    (pattern[j] == 1 && nums[i + j + 1] <= nums[i + j]) ||
                    (pattern[j] == -1 && nums[i + j + 1] >= nums[i + j])) {
                    match = false;
                    break;
                }
            }

            if (match) res++;
        }

        return res;
    }
}

