public class Solution {
    public int minOperations(int k) {
        int sum = 1;
        int count = 0;

        while (sum < k) {
            if ((k - sum) % sum == 0) {
                return count + (k - sum) / sum;
            }

            sum *= 2;
            count++;
        }

        return count;
    }
}

