// #2024_03_01_Time_59_ms_(69.95%)_Space_45.3_MB_(20.75%)
public class Solution {
    public long avoidObstacles(int[][] points) {
        Arrays.sort(points, (a, b) -> a[0] - b[0]);
        int n = points.length;
        boolean[] usedX = new boolean[n];
        boolean[] usedY = new boolean[n];

        for (int i = 0; i < n; i++) {
            if (!usedX[i]) {
                usedX[i] = true;
                long count = 1;

                for (int j = i + 1; j < n; j++) {
                    if (points[j][0] > points[i][0] && !usedY[j]) {
                        usedY[j] = true;
                        count++;
                    }
                }

                for (int k = 0; k < n; k++) {
                    if (!usedX[k] || !usedY[k]) {
                        return count * (n - count);
                    }
                }
            }
        }

        return 0;
    }
}

