// #2024_03_04_Time_5_ms_(92.03%)_Space_44.5_MB_(91.30%)
import java.util.PriorityQueue;

public class Solution {
    public int earliestSecondToMarkIndices(int[] nums, int[] changeIndices) {
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> nums[b] - nums[a]);
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == 0) {
                pq.offer(i);
            }
        }

        int res = -1;
        for (int s = 0; s < changeIndices.length; s++) {
            if (!pq.isEmpty() && nums[pq.peek()] == 0) {
                res = s + 1;
                break;
            } else if (nums[changeIndices[s] - 1] > 0) {
                pq.offer(changeIndices[s] - 1);
                nums[changeIndices[s] - 1]--;
            }
        }

        return res == -1 && !pq.isEmpty() ? changeIndices.length : res;
    }
}

