import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int maximumLength(int[] nums) {
        Map<Integer, Integer> map = new HashMap<>();
        int maxLen = 0;

        for (int num : nums) {
            if (!map.containsKey(num)) {
                map.put(num, 1);
            } else {
                map.put(num, map.get(num) + 1);
            }
        }

        for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
            int count = entry.getValue();
            int num = entry.getKey();

            if (count >= 3 && isPowerOfTwo(count)) {
                maxLen = Math.max(maxLen, count * 2 - 1);
            } else if (count >= 2) {
                long squareRoot = (long) Math.sqrt(num);

                if (squareRoot * squareRoot == num && map.containsKey((int)squareRoot) && map.get((int)squareRoot) >= 1) {
                    int len = count + map.get((int)squareRoot);
                    maxLen = Math.max(maxLen, len * 2 - 1);
                }
            } else if (count == 1) {
                long squareRoot = (long) Math.sqrt(num);

                if (squareRoot * squareRoot == num && map.containsKey((int)squareRoot) && map.get((int)squareRoot) >= 2) {
                    maxLen = Math.max(maxLen, 3);
                }
            }
        }

        return maxLen;
    }

    private boolean isPowerOfTwo(int n) {
        if (n <= 0) {
            return false;
        }

        while (n > 1) {
            if ((n & 1) == 1) {
                return false;
            }
            n >>= 1;
        }

        return true;
    }
}

