public class Solution {
    public int[] distributeArray(int[][] nums) {
        TreeSet<Integer> set1 = new TreeSet<>((a, b) -> Integer.compare(b, a));
        TreeSet<Integer> set2 = new TreeSet<>((a, b) -> Integer.compare(b, a));

        for (int i = 0; i < nums.length; i++) {
            if (set1.size() == set2.size()) {
                if (greaterCount(set1, nums[i][0]) > greaterCount(set2, nums[i][0])) {
                    set2.add(nums[i][0]);
                } else if (greaterCount(set1, nums[i][0]) < greaterCount(set2, nums[i][0])) {
                    set1.add(nums[i][0]);
                } else {
                    set1.add(nums[i][0]);
                }
            } else if (set1.size() > set2.size()) {
                if (greaterCount(set1, nums[i][0]) >= greaterCount(set2, nums[i][0])) {
                    set2.add(nums[i][0]);
                } else {
                    set1.add(nums[i][0]);
                }
            } else {
                if (greaterCount(set1, nums[i][0]) <= greaterCount(set2, nums[i][0])) {
                    set1.add(nums[i][0]);
                } else {
                    set2.add(nums[i][0]);
                }
            }
        }

        int[] result = new int[nums.length];
        int i = 0;
        for (Integer num : set1) {
            result[i++] = num;
        }
        for (Integer num : set2) {
            result[i++] = num;
        }
        return result;
    }

    private int greaterCount(TreeSet<Integer> set, int val) {
        return set.tailSet(val + 1).size();
    }
}

