public class Solution {
    public int countSubmatrices(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int[] rowSum = new int[n];
        int res = 0;

        for (int i = 0; i < m; i++) {
            for (int j = i; j < m; j++) {
                for (int col = 0; col < n; col++) {
                    if (i == j) rowSum[col] = grid[i][col];
                    else rowSum[col] += grid[j][col];
                }

                int sum = 0;
                for (int r = 0; r < n; r++) {
                    sum += rowSum[r];
                    if (sum > k) {
                        int tmp = sum - rowSum[r];
                        while (tmp <= k && r >= 1) {
                            tmp += rowSum[r-1];
                            res++;
                            r--;
                        }
                    } else res++;
                }
            }
        }

        return res;
    }
}

