public class Solution {
    public int[][] resultGrid(int[][] image, int threshold) {
        int m = image.length;
        int n = image[0].length;
        int[][] res = new int[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                List<Integer> list = new ArrayList<>();

                for (int x = Math.max(0, i - 1); x <= Math.min(m - 1, i + 1); x++) {
                    for (int y = Math.max(0, j - 1); y <= Math.min(n - 1, j + 1); y++) {
                        boolean flag = true;

                        for (int a = Math.max(0, x - 1); a <= Math.min(m - 1, x + 1); a++) {
                            for (int b = Math.max(0, y - 1); b <= Math.min(n - 1, y + 1); b++) {
                                if (Math.abs(image[a][b] - image[x][y]) > threshold) {
                                    flag = false;
                                    break;
                                }
                            }
                        }

                        if (flag) list.add(image[x][y]);
                    }
                }

                int sum = 0;
                for (int num : list) sum += num;
                res[i][j] = sum / list.size();
            }
        }

