        for (int i = 0; i < n; i++) {
            boolean[] visited = new boolean[n];
            Map<Integer, Integer> map1 = dfs(graph, i, signalSpeed, visited);

            visited = new boolean[n];
            Map<Integer, Integer> map2 = dfs(graph, i, signalSpeed, visited);
            for (int key : map1.keySet()) {
                if (!map2.containsKey(key)) continue;
                count[i] += map1.get(key) * map2.get(key);
            }
        }

        return count;
    }

    private Map<Integer, Integer> dfs(List<Integer>[] graph, int u, int signalSpeed, boolean[] visited) {
        visited[u] = true;
        Map<Integer, Integer> map = new HashMap<>();
        for (int v : graph[u]) {
            if (!visited[v]) {
                int dist = 1;
                Map<Integer, Integer> subMap = dfs(graph, v, signalSpeed, visited);
                for (int key : subMap.keySet()) {
                    map.put(key + dist, map.getOrDefault(key + dist, 0) + subMap.get(key));
                }
            }
        }

        int rem = u % signalSpeed;
        if (!map.containsKey(rem)) map.put(rem, 0);
        map.put(rem, map.get(rem) + 1);

