public class Solution {
    public int sumOfPrices(int k, int x) {
        int left = 0;
        int right = Integer.MAX_VALUE - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (check(mid, k, x)) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return right;
    }

    private boolean check(int num, int k, int x) {
        long sum = 0;

        for (int i = 1; i <= num; i++) {
            String binaryString = Integer.toBinaryString(i);
            for (int j = 0; j < binaryString.length(); j++) {
                if ((j + 1) % x == 0 && binaryString.charAt(binaryString.length() - 1 - j) == '1') {
                    sum++;
                }
            }

            if (sum > k) return false;
        }

        return true;
    }
}

