public class Solution {
    public long[] countOfPairs(int n, int x, int y) {
        long[] result = new long[n];

        // Calculate pairs with distance k without considering the additional street
        for (int k = 1; k < n; k++) {
            result[k] += (long)(n - k) * (k + 1);
        }

        // Adjust counts based on the additional street
        int minXY = Math.min(x, y), maxXY = Math.max(x, y);
        for (int k = 0; k < n; k++) {
            if (minXY <= k + 1 && maxXY > k + 1) {
                result[k] -= (long)(maxXY - minXY - 1) * (k + 1);
            }
            if (n - maxXY >= k && n - minXY > k) {
                result[k] += (long)(minXY - 1) * (n - maxXY);
            }
        }

        // Handle the case where x and y are equal
        if (x == y) {
            for (int k = 0; k < n; k++) {
                result[k]++;
            }
        } else {
            int distance = Math.abs(x - y);
            result[distance]--;
        }

        return result;
    }
}

