public class Solution {
    public int shortestSubarray(int[] nums, int k) {
        int n = nums.length;
        long[] prefixSum = new long[n + 1];

        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] | nums[i];
        }

        int res = Integer.MAX_VALUE;
        for (int left = 0; left < n; left++) {
            if ((prefixSum[left] & k) == k) {
                continue;
            }

            int right = binarySearch(prefixSum, left + 1, n, prefixSum[left] | k);
            if (right != -1) {
                res = Math.min(res, right - left);
            }
        }

        return res == Integer.MAX_VALUE ? -1 : res;
    }

    private int binarySearch(long[] prefixSum, int start, int end, long target) {
        while (start < end) {
            int mid = start + (end - start) / 2;
            if ((prefixSum[mid] & target) == target) {
                end = mid;
            } else {
                start = mid + 1;
            }
        }

        return (prefixSum[start] & target) == target ? start : -1;
    }
}

