            if (count == nums.length) return s;

            int[] top = pq.peek();
            top[0]--;
            pq.offer(top);

            if (!marked[changeIndices[s - 1] - 1]) {
                marked[changeIndices[s - 1] - 1] = true;
                count++;
            }
        }

        return count == nums.length ? changeIndices.length : -1;
    }
}

