public class Solution {
    public long maximumStrength(int[] nums, int k) {
        int n = nums.length;
        long[] prefixSum = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + nums[i];
        }

        long[][] dp = new long[k + 1][n + 1];
        for (long[] row : dp) {
            java.util.Arrays.fill(row, Long.MIN_VALUE);
        }
        dp[0][0] = 0;

        for (int i = 1; i <= k; i++) {
            for (int j = i; j <= n; j++) {
                for (int x = 1; x <= j - i + 2; x++) {
                    long sum = prefixSum[j] - prefixSum[j - x];
                    dp[i][j] = Math.max(dp[i][j], dp[i - 1][j - x] + ((x % 2 == 1) ? sum : -sum) * (i));
                }
            }
        }

        return dp[k][n];
    }
}

