import java.util.Arrays;
import java.util.Random;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;
    private Random rand = new Random();

    public int sumOfPower(int[] nums, int k) {
        Arrays.sort(nums);
        long res = 0;
        for (int i = 0; i < nums.length; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue;
            long count = count(nums, k, i + 1, nums[i]);
            res += count * (count - 1) / 2 % MOD;
            res %= MOD;
        }
        return (int) res;
    }

    private long count(int[] nums, int target, int start, int val) {
        if (target < val) return 0;
        if (start == nums.length) return target == val ? 1 : 0;

        int end = find(nums, target - val + 1);
        if (end <= start) return 0;

        long res = count(nums, target, start + 1, val) * 2 % MOD;
        res += count(nums, target - nums[end], end, nums[end]);
        res %= MOD;
        return res;
    }

    private int find(int[] nums, int target) {
        int left = 0, right = nums.length - 1;
        while (left <= right) {
            int mid = left + rand.nextInt(right - left + 1);
            if (nums[mid] >= target) right = mid - 1;
            else left = mid + 1;
        }
        return left;
    }
}

