public class Solution {
    public long minimumCost(int[] nums, int k, int dist) {
        PriorityQueue<Integer> pq = new PriorityQueue<>(Comparator.comparingInt(a -> nums[a]));
        for (int i = 0; i < k; i++) {
            pq.offer(i);
        }

        long res = 0;
        for (int i = k; i <= nums.length - dist + k; i += dist) {
            int idx = pq.poll();
            res += nums[idx];
            if (i < nums.length) {
                pq.offer(i);
            }
        }

        while (!pq.isEmpty()) {
            int idx = pq.poll();
            if (idx >= nums.length - dist + k) {
                res += nums[idx];
            }
        }

        return res;
    }
}

