        int countOfCharsWithMoreThanTwoOccurrences = 0;

        for (int count : charCount.values()) {
            if (count > 2) {
                countOfCharsWithMoreThanTwoOccurrences++;
            }
        }

        return countOfCharsWithMoreThanTwoOccurrences == 0;
    }
}

