public class Solution {
    public int minimumTimeToInitialState(String w, int q) {
        int n = w.length();
        long base = 131;
        long mod = (long) Math.pow(10, 9) + 7;
        long[] pow = new long[n];
        pow[0] = 1;
        for (int i = 1; i < n; i++) {
            pow[i] = pow[i - 1] * base % mod;
        }

        long hash = 0;
        for (char c : w.toCharArray()) {
            hash = (hash + (c - 'a' + 1) * pow[n - 1]) % mod;
        }

        Set<Long> seen = new HashSet<>();
        seen.add(hash);

        int time = 0;
        while (true) {
            time++;
            hash = ((hash - (w.charAt(0) - 'a' + 1) * pow[n - 1] % mod + mod) % mod * base % mod + w.charAt(n - q)) % mod;
            if (seen.contains(hash)) {
                return time;
            }
            seen.add(hash);
            w = w.substring(q) + w.substring(0, q);
        }
    }
}

