public class Solution {
    public boolean canSortArray(int[] nums) {
        int n = nums.length;
        int[] countBits = new int[n];

        // Count set bits for each number in the array
        for (int i = 0; i < n; i++) {
            countBits[i] = Integer.bitCount(nums[i]);
        }

        // Create a copy of the original array and sort it
        int[] sortedNums = nums.clone();
        java.util.Arrays.sort(sortedNums);

        // Count set bits for each number in the sorted array
        int[] sortedCountBits = new int[n];
        for (int i = 0; i < n; i++) {
            sortedCountBits[i] = Integer.bitCount(sortedNums[i]);
        }

        // Compare the two arrays of bit counts. If they are equal, then we can sort the array.
        return java.util.Arrays.equals(countBits, sortedCountBits);
    }
}

