// #2022_05_26_Time_40_ms_(93.75%)_Space_92.9_MB_(71.71%)
public class Solution {
    public int countHighestScoreNodes(int[] parents) {
        int n = parents.length;
        List<Integer>[] children = new List[n];
        for (int i = 0; i < n; i++) {
            children[i] = new ArrayList<>();
        }

        for (int i = 1; i < n; i++) {
            children[parents[i]].add(i);
        }

        long maxScore = -1;
        int count = 0;

        dfs(children, 0, n, maxScore, count);

        return count;
    }

    private long[] dfs(List<Integer>[] children, int node, int n, long maxScore, int count) {
        long score = 1;
        int remainingNodes = n - 1;

        for (int child : children[node]) {
            long[] result = dfs(children, child, n, maxScore, count);
            score *= result[0];
            remainingNodes -= (int)result[1];
        }

        if (remainingNodes > 0) {
            score *= remainingNodes;
        }

        if (score > maxScore) {
            maxScore = score;
            count = 1;
        } else if (score == maxScore) {
            count++;
        }

        return new long[]{maxScore, n - remainingNodes};
    }
}

