public class Solution {
    public int networkBecomesIdle(int[][] edges, int[] patience) {
        int n = patience.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        dist[0] = 0;
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(0);

        while (!queue.isEmpty()) {
            int node = queue.poll();
            for (int neighbor : graph[node]) {
                if (dist[neighbor] == -1) {
                    dist[neighbor] = dist[node] + 1;
                    queue.offer(neighbor);
                }
            }
        }

        int maxTime = 0;
        for (int i = 1; i < n; i++) {
            int d = dist[i];
            if (d == 0) continue;
            int time = d * 2;
            int fullCycles = time / patience[i];
            if (time % patience[i] != 0) fullCycles++;
            maxTime = Math.max(maxTime, fullCycles * patience[i] + d);
        }

        return maxTime + 1;
    }
}

