        for (int[] dir : DIRECTIONS) {
            int nx = x + dir[0];
            int ny = y + dir[1];

            if (nx >= 0 && nx < 8 && ny >= 0 && ny < 8 && !visited[nx][ny]) {
                visited[nx][ny] = true;
                path.add(nx * 8 + ny);
                dfsQueen(nx, ny, visited, path, n);
                path.remove(path.size() - 1);
                visited[nx][ny] = false;
