        }
    }

    private void dfsRook(int x, int y, boolean[][] visited, List<Integer> path, int n) {
        if (path.size() == n) {
            VISITED.add(hash(path));
            return;
        }

        for (int[] dir : Arrays.copyOfRange(DIRECTIONS, 0, 4)) {
            int nx = x + dir[0];
            int ny = y + dir[1];

            if (nx >= 0 && nx < 8 && ny >= 0 && ny < 8 && !visited[nx][ny]) {
                visited[nx][ny] = true;
                path.add(nx * 8 + ny);
                dfsRook(nx, ny, visited, path, n);
                path.remove(path.size() - 1);
                visited[nx][ny] = false;
            }
        }
    }

    private int hash(List<Integer> path) {
        int res = 0;

        for (int i : path) {
            res ^= i;
        }

        return res;
    }
}

