// #Hard #Graph #Union_Find #2022_05_29_Time_102_ms_(55.25%)_Space_54.4_MB_(55.25%)
public class Solution {
    public boolean[] friendRequests(int n, int[][] restrictions, int[][] requests) {
        UnionFind uf = new UnionFind(n);
        boolean[] result = new boolean[requests.length];

        for (int i = 0; i < requests.length; i++) {
            int u = requests[i][0], v = requests[i][1];
            if (!uf.hasCycle(u, v, restrictions)) {
                uf.union(u, v);
                result[i] = true;
            }
        }

        return result;
    }

    class UnionFind {
        private int[] parent;
        private int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];

            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);

            if (rootX == rootY) {
                return;
            }

            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }

        public boolean hasCycle(int u, int v, int[][] restrictions) {
            Set<Integer> setU = new HashSet<>();
            Set<Integer> setV = new HashSet<>();

            for (int[] restriction : restrictions) {
                if ((restriction[0] == u && find(restriction[1]) == find(v)) || 
                    (find(restriction[0]) == find(u) && restriction[1] == v) ||
                    (restriction[0] == v && find(restriction[1]) == find(u)) || 
                    (find(restriction[0]) == find(v) && restriction[1] == u)) {
                    return true;
                }

                if (find(restriction[0]) == find(u)) {
                    setU.add(find(restriction[1]));
                } else if (find(restriction[0]) == find(v)) {
                    setV.add(find(restriction[1]));
                }
            }

            for (int x : setU) {
                if (setV.contains(x)) {
                    return true;
                }
            }

            return false;
        }
    }
}

