public class Solution {
    public boolean placeWordInCrossword(char[][] board, String word) {
        char[] chars = word.toCharArray();
        int m = board.length;
        int n = board[0].length;

        // Check horizontal placement
        for (int i = 0; i < m; i++) {
            for (int j = 0; j <= n - chars.length; j++) {
                if (canPlaceHorizontally(board, chars, i, j)) return true;
            }
            for (int j = chars.length - 1; j >= 0 && j + chars.length - 1 < n; j--) {
                if (canPlaceHorizontally(board, reverse(chars), i, j)) return true;
            }
        }

        // Check vertical placement
        for (int i = 0; i <= m - chars.length; i++) {
            for (int j = 0; j < n; j++) {
                if (canPlaceVertically(board, chars, i, j)) return true;
            }
            for (int j = chars.length - 1; j >= 0 && j + chars.length - 1 < m; j--) {
                if (canPlaceVertically(board, reverse(chars), i, j)) return true;
            }
        }

        return false;
    }

    private boolean canPlaceHorizontally(char[][] board, char[] word, int row, int col) {
        for (int i = 0; i < word.length; i++) {
            if ((col + i == 0 || board[row][col + i - 1] != ' ') && 
                (col + i == board[0].length - 1 || board[row][col + i + 1] != ' ') &&
                (board[row][col + i] == word[i] || board[row][col + i] == ' ')) {
            } else return false;
        }
        return true;
    }

    private boolean canPlaceVertically(char[][] board, char[] word, int row, int col) {
        for (int i = 0; i < word.length; i++) {
            if ((row + i == 0 || board[row + i - 1][col] != ' ') && 
                (row + i == board.length - 1 || board[row + i + 1][col] != ' ') &&
                (board[row + i][col] == word[i] || board[row + i][col] == ' ')) {
            } else return false;
        }
        return true;
    }

    private char[] reverse(char[] chars) {
        int left = 0, right = chars.length - 1;
        while (left < right) {
            char temp = chars[left];
            chars[left++] = chars[right];
            chars[right--] = temp;
        }
        return chars;
    }
}

