public class Solution {
    public int minimumDeletions(int[] nums) {
        int minIndex = 0, maxIndex = 0;
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] > nums[maxIndex]) {
                maxIndex = i;
            }
            if (nums[i] < nums[minIndex]) {
