public class Solution {
    public int maximalPathQuality(int[] values, int[][] edges, int maxTime) {
        int n = values.length;
        List<Node>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            int u = edge[0], v = edge[1], time = edge[2];
            graph[u].add(new Node(v, time));
            graph[v].add(new Node(u, time));
        }

        boolean[] visited = new boolean[n];
        int maxQuality = 0;

        backtrack(0, values[0], maxTime, graph, visited, values, maxQuality);

        return maxQuality;
    }

    private void backtrack(int node, int currentQuality, int remainingTime, List<Node>[] graph, boolean[] visited, int[] values, int maxQuality) {
        if (node == 0) {
            maxQuality = Math.max(maxQuality, currentQuality);
        }

        for (Node neighbor : graph[node]) {
            if (neighbor.time <= remainingTime) {
                int newRemainingTime = remainingTime - neighbor.time;
                if (!visited[neighbor.index]) {
                    visited[neighbor.index] = true;
                    backtrack(neighbor.index, currentQuality + values[neighbor.index], newRemainingTime, graph, visited, values, maxQuality);
                    visited[neighbor.index] = false;
                } else {
                    backtrack(neighbor.index, currentQuality, newRemainingTime, graph, visited, values, maxQuality);
                }
            }
        }
    }

    public class Solution {
        int index, time;

        public Node(int i, int time) {
            this.index = i;
            this.time = time;
        }
    }
}

