public class Solution {
    public int waysToPartition(int[] nums, int k) {
        Map<Integer, Integer> leftSums = new HashMap<>();
        Map<Integer, Integer> rightSums = new HashMap<>();

        int totalSum = 0;
        for (int num : nums) {
            totalSum += num;
        }

        int sum = 0;
        for (int i = 0; i < nums.length - 1; i++) {
            sum += nums[i];
            leftSums.put(sum, leftSums.getOrDefault(sum, 0) + 1);
        }

        sum = 0;
        for (int i = nums.length - 1; i > 0; i--) {
            sum += nums[i];
            rightSums.put(sum, rightSums.getOrDefault(sum, 0) + 1);
        }

        int maxWays = 0;

        if (totalSum % 2 == 0 && leftSums.containsKey(totalSum / 2)) {
            maxWays = leftSums.get(totalSum / 2);
        }

        for (int i = 0; i < nums.length; i++) {
            int diff = k - nums[i];
            if ((totalSum + diff) % 2 == 0) {
                int target = (totalSum + diff) / 2;
                maxWays = Math.max(maxWays, leftSums.getOrDefault(target - diff, 0) + rightSums.getOrDefault(target, 0));
            }
        }

        return maxWays;
    }
}

