public class Solution {
    public int minimumDifference(int[] nums) {
        int n = nums.length / 2;
        int sum = 0;
        for (int num : nums) {
            sum += num;
        }

        boolean[][] dp = new boolean[n + 1][sum / 2 + 1];
        dp[0][0] = true;

        for (int i = 0; i < n * 2; i++) {
            int cur = nums[i];
            for (int j = n - 1; j >= 0; j--) {
                for (int k = sum / 2; k >= cur; k--) {
                    dp[j + 1][k] |= dp[j][k - cur];
                }
            }
        }

        int maxSum = 0;
        for (int i = sum / 2; i >= 0; i--) {
            if (dp[n][i]) {
                maxSum = i;
                break;
            }
        }

        return sum - maxSum * 2;
    }
}

