import java.util.ArrayList;
import java.util.List;

public class Solution {
    public boolean possiblyEquals(String s1, String s2) {
        List<Integer> dp = new ArrayList<>();
        for (int i = 0; i < s1.length(); i++) {
            if (Character.isDigit(s1.charAt(i))) {
                int j = i;
                while (j + 1 < s1.length() && Character.isDigit(s1.charAt(j + 1)))
                    j++;
                dp.add(Integer.parseInt(s1.substring(i, j + 1)));
                i = j;
            } else
                dp.add(1);
        }

        List<Integer> dp2 = new ArrayList<>();
        for (int i = 0; i < s2.length(); i++) {
            if (Character.isDigit(s2.charAt(i))) {
                int j = i;
                while (j + 1 < s2.length() && Character.isDigit(s2.charAt(j + 1)))
                    j++;
                dp2.add(Integer.parseInt(s2.substring(i, j + 1)));
                i = j;
            } else
                dp2.add(1);
        }

        int m = dp.size(), n = dp2.size();
        boolean[][] memo = new boolean[m + 1][n + 1];
        return dfs(dp, dp2, 0, 0, 0, memo) || dfs(dp, dp2, 0, 0, 1, memo);
    }

    private boolean dfs(List<Integer> dp, List<Integer> dp2, int i, int j, int k, boolean[][] memo) {
        if (i == dp.size() && j == dp2.size())
            return true;

        if (memo[i][j])
            return false;

        memo[i][j] = true;

        if (k == 0) {
            if (i < dp.size()) {
                int sum = 0, count = 0;
                while (sum + dp.get(i) <= dp2.size() && i < dp.size()) {
                    sum += dp.get(i);
                    count++;
                    if (dfs(dp, dp2, i + count, j + sum, k ^ 1, memo))
                        return true;
                    i++;
                }
            } else
                return false;
        } else {
            if (j < dp2.size()) {
                int sum = 0, count = 0;
                while (sum + dp2.get(j) <= dp.size() && j < dp2.size()) {
                    sum += dp2.get(j);
                    count++;
                    if (dfs(dp, dp2, i + sum, j + count, k ^ 1, memo))
                        return true;
                    j++;
                }
            } else
                return false;
        }

        return false;
    }
}

