public class Solution {
    public int[] missingRolls(int[] rolls, int mean, int n) {
        int m = rolls.length;
        long totalSum = (long)mean * (m + n);
        long currentSum = 0;

        for (int roll : rolls) {
            currentSum += roll;
        }

        long missingSum = totalSum - currentSum;

        if (missingSum < n || missingSum > 6L * n) {
            return new int[0];
        }

        int[] result = new int[n];
        for (int i = 0; i < n; i++) {
            result[i] = (int)(missingSum / n);
        }

        long remainder = missingSum % n;
        for (int i = 0; i < remainder; i++) {
            result[i]++;
        }

        return result;
    }
}

