                        for (Integer y : dp[n - j - 1]) {
                            temp.add(x + y);
                        }
                    }
                    dp[j] = temp;
                }
            } else if (c == '*') {
                for (int j = 0; j < n; j++) {
                    Set<Integer> temp = new HashSet<>(dp[j]);
                    for (Integer x : dp[j]) {
                        for (Integer y : dp[n - j - 1]) {
                            temp.add(x * y);
                        }
                    }
                    dp[j] = temp;
                }
            } else {
                int num = c - '0';
                Set<Integer> temp = new HashSet<>();
                for (int j = 0; j < n; j++) {
                    if (j == 0 || s.charAt(j - 1) != '*') {
                        temp.add(num);
                    }
                }
                dp[n] = temp;
            }
        }

        int correctAnswer = eval(s);

        int score = 0;
        for (int answer : answers) {
            if (answer == correctAnswer) {
                score += 5;
            } else if (dp[n].contains(answer)) {
                score += 2;
            }
        }

        return score;
    }

    private int eval(String s) {
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        char sign = '+';
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '+' || s.charAt(i) == '*') {
                sign = s.charAt(i);
            } else if (i == s.length() - 1 || s.charAt(i + 1) == '+' || s.charAt(i + 1) == '*') {
                int num = s.charAt(i) - '0';
                if (sign == '+') {
                    stack.push(num);
                } else if (sign == '*') {
                    stack.push(stack.pop() * num);
                }
            }
        }

        int sum = 0;
        while (!stack.isEmpty()) {
            sum += stack.pop();
        }
        return sum;
    }
}

