public class Solution {
    public int maxTwoEvents(int[][] events) {
        Arrays.sort(events, (a, b) -> a[0] - b[0]);

        int[] maxEndingHere = new int[events.length];
        maxEndingHere[0] = events[0][2];
        for (int i = 1; i < events.length; i++) {
            maxEndingHere[i] = Math.max(maxEndingHere[i-1], events[i][2]);
        }

        int res = 0;
        for (int i = 0; i < events.length; i++) {
            int lo = 0, hi = i - 1;
            while (lo <= hi) {
                int mid = lo + (hi - lo) / 2;
                if (events[mid][1] < events[i][0]) {
                    res = Math.max(res, maxEndingHere[mid] + events[i][2]);
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
        }

        return Math.max(res, Arrays.stream(maxEndingHere).max().getAsInt());
    }
}

