        int n = security.length;
        int[] dec = new int[n];
        int[] inc = new int[n];

        for (int i = 1; i < n; i++) {
            if (security[i - 1] >= security[i]) {
                dec[i] = dec[i - 1] + 1;
            }
        }

        for (int i = n - 2; i >= 0; i--) {
            if (security[i] <= security[i + 1]) {
                inc[i] = inc[i + 1] + 1;
            }
        }

