import java.util.*;

public class Solution {
    public int maxProduct(String s) {
        int n = s.length();
        boolean[][] isP = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            isP[i][i] = true;
        }
        for (int i = 0; i + 1 < n; i++) {
            if (s.charAt(i) == s.charAt(i + 1)) {
                isP[i][i + 1] = true;
            }
        }
        for (int len = 3; len <= n; len++) {
            for (int start = 0; start + len - 1 < n; start++) {
                if (s.charAt(start) == s.charAt(start + len - 1)) {
                    isP[start][start + len - 1] = isP[start + 1][start + len - 2];
                }
            }
        }

        int[] dp = new int[1 << n];
        for (int mask = 0; mask < (1 << n); mask++) {
            List<Integer> list = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    list.add(i);
                }
            }

            int len = list.size();
            boolean isPalin = true;
            for (int i = 0, j = len - 1; i < j; i++, j--) {
                if (!isP[list.get(i)][list.get(j)]) {
                    isPalin = false;
                    break;
                }
            }

            if (isPalin) {
                dp[mask] = len * len;
            } else {
                for (int subMask = mask - 1; subMask > 0; subMask--) {
                    if ((mask & subMask) == subMask) {
                        int otherSubMask = mask ^ subMask;
                        dp[mask] = Math.max(dp[mask], dp[subMask] + dp[otherSubMask]);
                    }
                }
            }
        }

        return dp[(1 << n) - 1];
    }
}

