// #Medium #Linked_List #2022_05_29_Time_9_ms_(62.36%)_Space_270.4_MB_(37.64%)
import com_github_leetcode.ListNode;

public class Solution {
    public ListNode reverseEvenLengthGroups(ListNode head) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode prev = dummy, curr = head;
        int groupSize = 1;

        while (curr != null) {
            int count = 0;
            ListNode tail = curr;

            // Count the number of nodes in the current group
            while (tail != null && count < groupSize) {
                tail = tail.next;
                count++;
            }

            if (count % 2 == 0) {
                // Reverse the nodes in the current group
                ListNode nextGroupHead = tail;
                prev.next = reverse(curr, count);
                curr = prev.next;

                // Move to the next group
                while (curr != null && curr.next != nextGroupHead) {
                    curr = curr.next;
                }
            } else {
                // Move to the next group without reversing
                for (int i = 0; i < count; i++) {
                    prev = prev.next;
                }
                curr = prev.next;
            }

            groupSize++;
        }

        return dummy.next;
    }

    private ListNode reverse(ListNode head, int count) {
        ListNode prev = null, curr = head, nextTemp = null;

        for (int i = 0; i < count; i++) {
            nextTemp = curr.next;
            curr.next = prev;
            prev = curr;
            curr = nextTemp;
        }

        return prev;
    }
}

