    private boolean isValidWord(String word) {
        int hyphenCount = 0;
        int punctuationCount = 0;

        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);

            if (Character.isDigit(c)) {
                return false;
            }

            if (c == '-') {
                hyphenCount++;

                if (hyphenCount > 1 || i == 0 || i == word.length() - 1 || !Character.isLetter(word.charAt(i - 1)) || !Character.isLetter(word.charAt(i + 1))) {
                    return false;
                }
            } else if (!Character.isLetter(c) && c != ' ') {
                punctuationCount++;

                if (punctuationCount > 1 || i != word.length() - 1) {
                    return false;
                }
            }
        }

        return true;
    }
}

