public class Solution {
    public int[] platesBetweenCandles(String s, int[][] queries) {
        int n = s.length();
        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + (s.charAt(i) == '|' ? 1 : 0);
        }

        int m = queries.length;
        int[] res = new int[m];

        for (int i = 0; i < m; i++) {
            int left = queries[i][0];
            int right = queries[i][1];

            int leftCandle = findNextCandle(prefixSum, left);
            if (leftCandle == -1 || leftCandle >= right) continue;

            int rightCandle = findPrevCandle(prefixSum, right + 1);
            if (rightCandle <= left) continue;

            res[i] = rightCandle - leftCandle - (prefixSum[rightCandle] - prefixSum[leftCandle]);
        }

        return res;
    }

    private int findNextCandle(int[] prefixSum, int start) {
        while (start < prefixSum.length && prefixSum[start + 1] == prefixSum[start]) start++;
        if (start >= prefixSum.length) return -1;
        return start;
    }

    private int findPrevCandle(int[] prefixSum, int end) {
        while (end > 0 && prefixSum[end - 1] == prefixSum[end]) end--;
        if (end <= 0) return -1;
        return end - 1;
    }
}

