import com_github_leetcode.ListNode;
import java.util.ArrayList;
import java.util.Collections;

public class Solution {
    public int[] nodesBetweenCriticalPoints(ListNode head) {
        ArrayList<Integer> criticals = new ArrayList<>();
        ListNode prev = null, next = null;
        int idx = 0;

        while (head.next != null) {
            next = head.next;
            if ((prev == null || head.val > prev.val) && head.val > next.val) 
                criticals.add(idx);
            else if ((prev == null || head.val < prev.val) && head.val < next.val)
                criticals.add(idx);

            prev = head;
            head = head.next;
            idx++;
        }

        if (criticals.size() < 2) return new int[]{-1, -1};

        Collections.sort(criticals);
        int minDistance = Integer.MAX_VALUE, maxDistance = Integer.MIN_VALUE;

        for (int i = 0; i < criticals.size() - 1; i++) {
            minDistance = Math.min(minDistance, criticals.get(i + 1) - criticals.get(i));
            maxDistance = Math.max(maxDistance, criticals.get(i + 1) - criticals.get(i));
        }

        return new int[]{minDistance, maxDistance};
    }
}

