        long result = Long.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            long top = prefixSumTop[n] - prefixSumTop[i + 1];
            long bottom = prefixSumBottom[i];

            if (top > bottom) {
                result = Math.min(result, top);
            } else {
                result = Math.min(result, bottom);
            }
        }

        return result;
    }
}

