public class Solution {
    public int countPyramids(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int res = 0;

        // Count pyramidal plots from top to bottom
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int left = j, right = j;
                    while (left > 0 && grid[i][left - 1] == 1) left--;
                    while (right < n - 1 && grid[i][right + 1] == 1) right++;
                    int width = right - left + 1;
                    if (width > 2 * (i + 1)) res += width - 2 * (i + 1);
                }
            }
        }

        // Count inverse pyramidal plots from bottom to top
        for (int i = m - 1; i >= 0; i--) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int left = j, right = j;
                    while (left > 0 && grid[i][left - 1] == 1) left--;
                    while (right < n - 1 && grid[i][right + 1] == 1) right++;
                    int width = right - left + 1;
                    if (width > 2 * (m - i)) res += width - 2 * (m - i);
                }
            }
        }

        return res;
    }
}

