// #Medium #String #Depth_First_Search #Tree #Binary_Tree
// #2022_05_25_Time_30_ms_(76.29%)_Space_109.4_MB_(43.13%)
import com_github_leetcode.TreeNode;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public String getDirections(TreeNode root, int startValue, int destValue) {
        Map<Integer, TreeNode> parents = new HashMap<>();
        dfs(root, null, parents);

        TreeNode startNode = parents.get(startValue);
        TreeNode destNode = parents.get(destValue);

        StringBuilder pathToStart = new StringBuilder();
        while (startNode != root) {
            if (startNode == startNode.parent.left) {
                pathToStart.insert(0, "L");
            } else {
                pathToStart.insert(0, "R");
            }
            startNode = startNode.parent;
        }

        StringBuilder pathFromDest = new StringBuilder();
        while (destNode != root) {
            if (destNode == destNode.parent.left) {
                pathFromDest.append("L");
            } else {
                pathFromDest.append("R");
            }
            destNode = destNode.parent;
        }

        int commonPrefixLength = 0;
        for (; commonPrefixLength < Math.min(pathToStart.length(), pathFromDest.length()); commonPrefixLength++) {
            if (pathToStart.charAt(commonPrefixLength) != pathFromDest.charAt(commonPrefixLength)) {
                break;
            }
        }

        StringBuilder result = new StringBuilder();
        for (int i = 0; i < pathToStart.length() - commonPrefixLength; i++) {
            result.append("U");
        }
        result.append(pathFromDest.substring(0, commonPrefixLength));
        return result.toString();
    }

    private void dfs(TreeNode node, TreeNode parent, Map<Integer, TreeNode> parents) {
        if (node == null) {
            return;
        }
        node.parent = parent;
        parents.put(node.val, node);
        dfs(node.left, node, parents);
        dfs(node.right, node, parents);
    }
}

