import java.util.Stack;

// #Hard #String #Greedy #Stack #Monotonic_Stack
// #2022_05_25_Time_131_ms_(64.46%)_Space_72.3_MB_(46.99%)
public class Solution {
    public String smallestSubsequence(String s, int k, char letter, int repetition) {
        Stack<Character> stack = new Stack<>();
        int[] count = new int[26];

        for (char c : s.toCharArray()) {
            count[c - 'a']++;
        }

        for (char c : s.toCharArray()) {
            while (!stack.isEmpty() && 
                   stack.peek() > c && 
                   stack.size() + s.length() - count[c - 'a'] >= k) {
                if (stack.pop() == letter) repetition++;
            }

            if (stack.size() < k && (stack.isEmpty() || stack.peek() != c)) {
                while (!stack.isEmpty() && repetition > 0 && stack.peek() == letter) {
                    stack.pop();
                    repetition--;
                }

                stack.push(c);
            }

            count[c - 'a']--;
        }

        StringBuilder sb = new StringBuilder();
        for (char c : stack) {
            if (c != letter || repetition-- > 0) {
                sb.append(c);
            }
        }

        while (sb.length() < k) {
            sb.append(letter);
        }

        return sb.toString();
    }
}

