public class Solution {
    public int maxConsecutiveAnswers(String answerKey, int k) {
        return Math.max(maxConsecutive('T', 'F', answerKey, k), maxConsecutive('F', 'T', answerKey, k));
    }

    private int maxConsecutive(char c1, char c2, String answerKey, int k) {
        int left = 0;
        int count = 0;
        int result = 0;

        for (int right = 0; right < answerKey.length(); right++) {
            if (answerKey.charAt(right) == c2) {
                count++;
            }

            while (count > k) {
                if (answerKey.charAt(left) == c2) {
                    count--;
                }
                left++;
            }

            result = Math.max(result, right - left + 1);
        }

        return result;
    }
}

