import java.util.Arrays;
import java.util.Deque;
import java.util.LinkedList;

public class Solution {
    public int maxTaskAssign(int[] tasks, int[] workers, int pills, int strength) {
        Arrays.sort(tasks);
        Arrays.sort(workers);

        Deque<Integer> deque = new LinkedList<>();
        for (int worker : workers) {
            deque.offer(worker + strength);
        }

        int low = 0;
        int high = Math.min(tasks.length, workers.length);

        while (low < high) {
            int mid = low + (high - low + 1) / 2;

            if (canAssign(mid, tasks, deque, pills)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }

        return low;
    }

    private boolean canAssign(int k, int[] tasks, Deque<Integer> deque, int pills) {
        for (int i = 0; i < k; i++) {
            if (!deque.isEmpty() && deque.peekLast() >= tasks[tasks.length - 1 - i]) {
                deque.pollLast();
            } else if (pills > 0 && !deque.isEmpty() && deque.peekFirst() + strength >= tasks[tasks.length - 1 - i]) {
                pills--;
                deque.pollFirst();
            } else {
                return false;
            }
        }

        return true;
    }
}

