import java.util.*;

// #Hard #Breadth_First_Search #Graph #Shortest_Path
// #2022_05_26_Time_65_ms_(74.03%)_Space_51.6_MB_(97.24%)
public class Solution {
    public int secondMinimum(int n, int[][] edges, int time, int change) {
        List<Integer>[] graph = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        int[][] dist = new int[n + 1][2];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dist[i], Integer.MAX_VALUE);
        }

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        dist[1][0] = 0;
        pq.offer(new int[] {0, 1});

        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int d = cur[0];
            int node = cur[1];

            if (d > dist[node][1]) continue;

            for (int nei : graph[node]) {
                int newD = d + time;
                if ((newD / change) % 2 == 1) newD += change - (newD % change);

                if (dist[nei][0] == Integer.MAX_VALUE || dist[nei][1] > newD) {
                    if (dist[nei][0] != Integer.MAX_VALUE && dist[nei][0] < newD) {
                        pq.offer(new int[] {newD, nei});
                    } else {
                        if (dist[nei][0] == Integer.MAX_VALUE || dist[nei][1] > dist[nei][0]) {
                            pq.offer(new int[] {Math.min(dist[nei][1], newD), nei});
                        }
                        dist[nei][1] = Math.max(dist[nei][1], newD);
                    }

                    if (dist[nei][0] == Integer.MAX_VALUE || dist[nei][0] > newD) {
                        pq.offer(new int[] {newD, nei});
                        dist[nei][0] = newD;
                    } else {
                        dist[nei][1] = Math.max(dist[nei][1], newD);
                    }
                }
            }
        }

        return dist[n][1];
    }
}
